import os

def compress_file(path: str) -> str:
    # Check if the file exists
    if not os.path.exists(path):
        return "File does not exist"

    # Get the file extension
    _, ext = os.path.splitext(path)

    # Define the compression command based on the file extension
    if ext == '.txt':
        command = f"zip {path}.zip {path}"
    elif ext == '.jpg' or ext == '.png':
        command = f"compress -9 {path} {path}.gz"
    else:
        return "Unsupported file type"

    # Execute the compression command
    try:
        os.system(command)
        return f"File compressed successfully to {path}.zip or {path}.gz"
    except Exception as e:
        return f"Error compressing file: {e}"
