from typing import List

def min_slides(grid: List[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_valid(x, y):
        return 0 <= x < rows and 0 <= y < cols

    def bfs(start_x, start_y):
        queue = [(start_x, start_y)]
        visited = set()
        visited.add((start_x, start_y))

        while queue:
            for _ in range(len(queue)):
                x, y = queue.pop(0)

                for dx, dy in directions:
                    nx, ny = x + dx, y + dy
                    if is_valid(nx, ny) and grid[nx][ny] == '0' and (nx, ny) not in visited:
                        visited.add((nx, ny))
                        queue.append((nx, ny))

        return len(visited)

    min_slides = float('inf')

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == '1':
                min_slides = min(min_slides, bfs(i, j))

    return min_slides if min_slides != float('inf') else -1
