def balanced_ternary_str(n: int) -> str:
    if n == 0:
        return "0"

    digits = []
    while n != 0:
        remainder = n % 3
        if remainder == 2:
            digits.append('1')
            n = (n + 1) // 3
        elif remainder == -1:
            digits.append('-1')
            n = (n - 1) // 3
        else:
            digits.append(str(remainder))
            n //= 3

    # Reverse the list to get the correct order
    digits.reverse()
    return ''.join(digits)
