import re

def evaluate_expression(expression: str) -> float:
    # Use regular expressions to find all numbers and operators in the expression
    tokens = re.findall(r'\d+|\+|\-|\*|\/', expression)

    # Initialize the result with the first number
    result = float(tokens[0])

    # Iterate over the tokens starting from the second element
    for i in range(1, len(tokens), 2):
        operator = tokens[i]
        next_number = float(tokens[i + 1])

        if operator == '+':
            result += next_number
        elif operator == '-':
            result -= next_number
        elif operator == '*':
            result *= next_number
        elif operator == '/':
            result /= next_number

    return result

