def run_stack_machine(program: list[str]) -> list[int]:
    stack = []
    for instruction in program:
        if instruction.startswith('PUSH'):
            value = int(instruction.split()[1])
            stack.append(value)
        elif instruction == 'ADD':
            if len(stack) < 2:
                raise ValueError("Not enough values on the stack for ADD operation")
            b = stack.pop()
            a = stack.pop()
            stack.append(a + b)
        elif instruction == 'SUB':
            if len(stack) < 2:
                raise ValueError("Not enough values on the stack for SUB operation")
            b = stack.pop()
            a = stack.pop()
            stack.append(a - b)
        elif instruction == 'MUL':
            if len(stack) < 2:
                raise ValueError("Not enough values on the stack for MUL operation")
            b = stack.pop()
            a = stack.pop()
            stack.append(a * b)
        elif instruction == 'DIV':
            if len(stack) < 2:
                raise ValueError("Not enough values on the stack for DIV operation")
            b = stack.pop()
            a = stack.pop()
            if b == 0:
                raise ZeroDivisionError("Division by zero")
            stack.append(a // b)
        else:
            raise ValueError(f"Unknown instruction: {instruction}")
    return stack
