def tokenize_code(source: str) -> list[tuple[str, str]]:
    tokens = []
    i = 0
    while i < len(source):
        if source[i].isspace():
            i += 1
            continue
        elif source[i] == '#':
            # Skip comments
            while i < len(source) and source[i] != '\n':
                i += 1
        elif source[i].isalpha() or source[i].isdigit():
            # Collect identifier or number
            start = i
            while i < len(source) and (source[i].isalnum() or source[i] == '_'):
                i += 1
            tokens.append((source[start:i], 'IDENTIFIER' if source[start].isalpha() else 'NUMBER'))
        elif source[i] in ['(', ')', '{', '}', '[', ']']:
            # Collect operators and delimiters
            tokens.append((source[i], source[i]))
            i += 1
        else:
            # Handle special characters
            tokens.append((source[i], 'SPECIAL_CHAR'))
            i += 1
    return tokens
