def top_k_elements(nums: List[int], k: int) -> List[int]:
    if k == 0:
        return []

    # Use a min-heap to keep track of the top k elements
    import heapq
    min_heap = []

    for num in nums:
        if len(min_heap) < k:
            heapq.heappush(min_heap, num)
        else:
            if num > min_heap[0]:
                heapq.heappop(min_heap)
                heapq.heappush(min_heap, num)

    # The heap contains the k largest elements, so return them in sorted order
    return sorted(min_heap)
