def rolling_variance(nums: list[float], k: int) -> list[float]:
    if k <= 0 or k > len(nums):
        raise ValueError("k must be between 1 and the length of nums")

    n = len(nums)
    variance = []
    sum_sq_diff = 0

    for i in range(n):
        if i < k:
            sum_sq_diff += (nums[i] - nums[i]) ** 2
        else:
            sum_sq_diff += (nums[i] - nums[i - k + 1]) ** 2
            variance.append(sum_sq_diff / k)

    return variance

