def stabilize_sandpile(grid: List[List[int]]) -> List[List[int]]:
    def is_stable(grid):
        for i in range(len(grid)):
            for j in range(len(grid[0])):
                if grid[i][j] >= 4:
                    return False
        return True

    while not is_stable(grid):
        for i in range(len(grid)):
            for j in range(len(grid[0])):
                if grid[i][j] >= 4:
                    # Distribute excess sand
                    grid[i][j] -= 4
                    if i > 0:
                        grid[i-1][j] += 1
                    if i < len(grid) - 1:
                        grid[i+1][j] += 1
                    if j > 0:
                        grid[i][j-1] += 1
                    if j < len(grid[0]) - 1:
                        grid[i][j+1] += 1

    return grid
