from collections import deque

def count_shortest_paths(n: int, edges: list[tuple[int, int]], source: int, target: int) -> int:
    # Initialize the graph as an adjacency list
    graph = {i: [] for i in range(n)}
    for u, v in edges:
        graph[u].append(v)

    # Initialize the queue for BFS and a set to track visited nodes
    queue = deque([(source, 0)])
    visited = set([source])

    # Dictionary to store the shortest path length to each node
    shortest_paths = {source: 0}

    while queue:
        current, distance = queue.popleft()

        # If we reach the target, return the distance
        if current == target:
            return distance

        # Explore neighbors
        for neighbor in graph[current]:
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, distance + 1))
                shortest_paths[neighbor] = distance + 1

    # If no path is found, return -1 or handle as needed
    return -1
