def seating_arrangements(guests: List[str], conflicts: List[Tuple[str, str]]) -> List[List[str]]:
    # Create a graph to represent the conflicts
    graph = {guest: set() for guest in guests}
    for conflict in conflicts:
        graph[conflict[0]].add(conflict[1])
        graph[conflict[1]].add(conflict[0])

    def is_valid_seating(seating: List[str]) -> bool:
        # Check if any two guests in the seating arrangement are in conflict
        for i in range(len(seating)):
            for j in range(i + 1, len(seating)):
                if seating[i] in graph[seating[j]] or seating[j] in graph[seating[i]]:
                    return False
        return True

    def backtrack(seating: List[str], remaining_guests: List[str]) -> List[List[str]]:
        if not remaining_guests:
            return [seating]

        valid_arrangements = []
        for guest in remaining_guests:
            new_seating = seating + [guest]
            new_remaining_guests = remaining_guests.copy()
            new_remaining_guests.remove(guest)
            if is_valid_seating(new_seating):
                valid_arrangements.extend(backtrack(new_seating, new_remaining_guests))

        return valid_arrangements

    # Start the backtracking process with an empty seating arrangement and all guests
    return backtrack([], guests)
