from typing import List, Tuple

def seating_arrangements(guests: List[str], conflicts: List[Tuple[str, str]]) -> List[List[str]]:
    # Create a dictionary to represent the graph of guests and their conflicts
    graph = {guest: set() for guest in guests}
    for conflict in conflicts:
        graph[conflict[0]].add(conflict[1])
        graph[conflict[1]].add(conflict[0])

    def is_safe(seating: List[str], guest: str) -> bool:
        """Check if it's safe to place the guest at the given position."""
        for other_guest in seating:
            if (guest, other_guest) in conflicts or (other_guest, guest) in conflicts:
                return False
        return True

    def backtrack(seating: List[str], guests_left: List[str]) -> List[List[str]]:
        """Recursively try to find all valid seating arrangements."""
        if not guests_left:
            return [seating]

        arrangements = []
        for guest in guests_left:
            if is_safe(seating, guest):
                new_seating = seating + [guest]
                new_guests_left = guests_left.copy()
                new_guests_left.remove(guest)
                arrangements.extend(backtrack(new_seating, new_guests_left))
        return arrangements

    # Start the backtracking process with an empty seating arrangement
    return backtrack([], guests)
