import base64

def encrypt(key: bytes, plaintext: bytes) -> bytes:
    # Convert key and plaintext to base64 for uniformity
    key_base64 = base64.urlsafe_b64encode(key)
    plaintext_base64 = base64.urlsafe_b64encode(plaintext)

    # Encrypt using a simple XOR operation (for demonstration purposes)
    encrypted_blob = bytearray()
    for i in range(len(plaintext_base64)):
        encrypted_blob.append(plaintext_base64[i] ^ key_base64[i % len(key_base64)])

    return base64.urlsafe_b64encode(encrypted_blob)

def decrypt(key: bytes, blob: bytes) -> bytes:
    # Convert key and blob to base64 for uniformity
    key_base64 = base64.urlsafe_b64encode(key)
    blob_base64 = base64.urlsafe_b64decode(blob)

    # Decrypt using the same XOR operation
    decrypted_blob = bytearray()
    for i in range(len(blob_base64)):
        decrypted_blob.append(blob_base64[i] ^ key_base64[i % len(key_base64)])

    return base64.urlsafe_b64decode(decrypted_blob)

