def top_k_elements(nums: List[int], k: int) -> List[int]:
    if k == 0:
        return []

    # Create a dictionary to count occurrences of each number
    count = {}
    for num in nums:
        if num in count:
            count[num] += 1
        else:
            count[num] = 1

    # Sort the numbers by frequency and then by their value
    sorted_nums = sorted(count.items(), key=lambda x: (-x[1], x[0]))

    # Extract the top k elements
    top_k = [num for num, _ in sorted_nums[:k]]

    return top_k
