from collections import *

def count_climbing_steps(n: int) -> int:
    if n < 0:
        return 0
    if n == 0:
        return 1

    # Initialize a list to store the number of ways to reach each step
    dp = [0] * (n + 1)
    dp[0] = 1  # There's one way to stay at the ground level (doing nothing)

    for i in range(1, n + 1):
        if i >= 1:
            dp[i] += dp[i - 1]
        if i >= 2:
            dp[i] += dp[i - 2]
        if i >= 3:
            dp[i] += dp[i - 3]

    return dp[n]
