def count_climbing_steps(n: int) -> int:
    if n < 0:
        return 0
    elif n == 0:
        return 1
    else:
        # Base cases for n = 1, 2, 3
        if n == 1:
            return 1
        elif n == 2:
            return 2
        elif n == 3:
            return 4

        # Recursive case
        return count_climbing_steps(n - 1) + count_climbing_steps(n - 2) + count_climbing_steps(n - 3)
