from collections import Counter

def compute_mode(nums: list[int]) -> list[int]:
    if not nums:
        return []

    num_counts = Counter(nums)
    max_count = max(num_counts.values())
    modes = [num for num, count in num_counts.items() if count == max_count]

    return sorted(modes)
