def multiply_matrices(a: list[list[int]], b: list[list[int]]) -> list[list[int]]:
    if len(a[0]) != len(b):
        raise ValueError("Las matrices no son compatibles para multiplicación")

    m, k = len(a), len(a[0])
    n = len(b[0])

    result = [[0] * n for _ in range(m)]

    for i in range(m):
        for j in range(n):
            for l in range(k):
                result[i][j] += a[i][l] * b[l][j]

    return result
