def min_max_normalize(nums: List[float]) -> List[float]:
    if not nums:
        return []

    min_val = min(nums)
    max_val = max(nums)

    if min_val == max_val:
        return [0.0] * len(nums)

    normalized = [(x - min_val) / (max_val - min_val) for x in nums]
    rounded = [round(num, 2) for num in normalized]

    return rounded
