def balanced_ternary_str(n: int) -> str:
    if n == 0:
        return "0"

    digits = []
    while n != 0:
        remainder = n % 3
        if remainder == 1:
            digits.append('+')
        elif remainder == -1:
            digits.append('-')
        else:
            digits.append('0')
        n //= 3

    # Reverse the list to get the correct order
    digits.reverse()

    return ''.join(digits)
