def balanced_ternary_str(n: int) -> str:
    if n == 0:
        return "0"

    digits = []
    while n != 0:
        remainder = n % 3
        if remainder == 2:
            digits.append('-')
            n = n // 3 + 1
        elif remainder == -1:
            digits.append('+')
            n = n // 3 - 1
        else:
            digits.append(str(remainder))
            n //= 3

    # Reverse the list to get the correct order
    digits.reverse()

    return ''.join(digits)

# Example usage:
print(balanced_ternary_str(-5))  # Output: "-10+"
print(balanced_ternary_str(0))   # Output: "0"
print(balanced_ternary_str(10))  # Output: "+00+"

