def sparse_vector_dot(v1: Dict[int, float], v2: Dict[int, float]) -> float:
    # Initialize the dot product to zero
    dot_product = 0.0

    # Iterate over the keys of the first vector
    for index in v1.keys():
        if index in v2:
            # Add the product of the values at the same index to the dot product
            dot_product += v1[index] * v2[index]

    # Round the result to three decimal places
    return round(dot_product, 3)
