def count_set_bits_range(lo: int, hi: int) -> int:
    if lo > hi:
        return 0

    # Calculate the number of set bits in numbers from 0 to hi
    def count_set_bits(n: int) -> int:
        count = 0
        while n:
            count += n & 1
            n >>= 1
        return count

    # Calculate the number of set bits in numbers from 0 to lo - 1
    def count_set_bits_less_than_lo(n: int) -> int:
        count = 0
        for i in range(1, n + 1):
            count += count_set_bits(i)
        return count

    # Calculate the number of set bits in numbers from lo to hi
    return count_set_bits(hi) - count_set_bits_less_than_lo(lo - 1)
