def roman_char_distance(w1: str, w2: str) -> int:
    def char_distance(c1, c2):
        if c1 == c2:
            return 0
        elif c1 < c2:
            return 1 + char_distance(c1, chr(ord(c2) - 1))
        else:
            return 1 + char_distance(chr(ord(c1) + 1), c2)

    distance = 0
    for i in range(min(len(w1), len(w2))):
        distance += char_distance(w1[i], w2[i])

    return distance + abs(len(w1) - len(w2))

