def roman_char_distance(w1: str, w2: str) -> int:
    def char_distance(c1: str, c2: str) -> int:
        if c1 == c2:
            return 0
        elif c1 < c2:
            return ord(c2) - ord(c1)
        else:
            return ord(c1) - ord(c2)

    distance = 0
    len1, len2 = len(w1), len(w2)
    min_len = min(len1, len2)

    for i in range(min_len):
        distance += char_distance(w1[i], w2[i])

    # Add the remaining characters from the longer string
    distance += abs(len1 - len2)

    return distance
