from collections import *

def count_subsequence_matches(text: str, sub: str) -> int:
    if len(sub) > len(text):
        return 0

    # Initialize a DP table where dp[i][j] represents the number of ways to form sub[:j+1] from text[:i+1]
    dp = [[0] * (len(sub) + 1) for _ in range(len(text) + 1)]

    # Base case: there's one way to form an empty subsequence from any text (by choosing no characters)
    for i in range(len(text) + 1):
        dp[i][0] = 1

    # Fill the DP table
    for i in range(1, len(text) + 1):
        for j in range(1, len(sub) + 1):
            if text[i - 1] == sub[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + dp[i - 1][j]
            else:
                dp[i][j] = dp[i - 1][j]

    return dp[len(text)][len(sub)]
