    # Convert the hash object to a hexadecimal string and return it
    return hash_object.hexdigest()[:32].lower()

import hashlib

def api_key_fingerprint(api_key: str) -> str:
    # Use SHA-256 hashing to generate a fixed-length hash
    hash_object = hashlib.sha256(api_key.encode())
    # Convert the hash object to a hexadecimal string and return it
    return hash_object.hexdigest()[:32].lower()

