from typing import List

def min_coins_bounded(coins: List[int], limits: List[int], target: int) -> int:
    if target == 0:
        return 0

    # Initialize a DP array to store the minimum coins needed for each amount
    dp = [float('inf')] * (target + 1)
    dp[0] = 0  # Base case: 0 coins needed to make 0 amount

    for i in range(1, target + 1):
        for j in range(len(coins)):
            coin_value = coins[j]
            limit = limits[j]

            if coin_value <= i and limit > 0:
                for k in range(1, limit + 1):
                    new_amount = i - k * coin_value
                    if new_amount >= 0:
                        dp[i] = min(dp[i], dp[new_amount] + k)

    return dp[target] if dp[target] != float('inf') else -1

