def longest_bitonic_length(nums: List[int]) -> int:
    if not nums:
        return 0

    n = len(nums)
    increasing = [1] * n
    decreasing = [1] * n

    # Fill increasing array
    for i in range(1, n):
        for j in range(i):
            if nums[i] > nums[j]:
                increasing[i] = max(increasing[i], increasing[j] + 1)

    # Fill decreasing array
    for i in range(n - 2, -1, -1):
        for j in range(n - 1, i, -1):
            if nums[i] > nums[j]:
                decreasing[i] = max(decreasing[i], decreasing[j] + 1)

    # Find the longest bitonic subsequence length
    return max(increasing[i] + decreasing[i] - 1 for i in range(n))
