import hashlib

def derive_key(passphrase: str, salt: bytes) -> bytes:
    # Ensure the passphrase is a string and the salt is a bytes object
    if not isinstance(passphrase, str):
        raise ValueError("Passphrase must be a string.")
    if not isinstance(salt, bytes):
        raise ValueError("Salt must be a bytes object.")

    # Use SHA-256 for key derivation
    key = hashlib.sha256((passphrase.encode('utf-8') + salt)).digest()

    # Ensure the key is exactly 32 bytes long
    if len(key) != 32:
        raise ValueError("Derived key must be exactly 32 bytes long.")

    return key

