from typing import List

def longest_bitonic_length(nums: List[int]) -> int:
    if not nums:
        return 0

    n = len(nums)

    # Step 1: Find the longest increasing subsequence (LIS) for each element
    lis = [1] * n
    for i in range(1, n):
        for j in range(i):
            if nums[i] > nums[j]:
                lis[i] = max(lis[i], lis[j] + 1)

    # Step 2: Find the longest decreasing subsequence (LDS) for each element
    lds = [1] * n
    for i in range(n - 2, -1, -1):
        for j in range(n - 1, i, -1):
            if nums[i] > nums[j]:
                lds[i] = max(lds[i], lds[j] + 1)

    # Step 3: The length of the longest bitonic subsequence is the maximum sum of LIS and LDS for any element
    max_bitonic_length = 0
    for i in range(n):
        max_bitonic_length = max(max_bitonic_length, lis[i] + lds[i] - 1)

    return max_bitonic_length
