from collections import defaultdict

def count_shortest_paths(n: int, edges: list[tuple[int, int]], source: int, target: int) -> int:
    if source == target:
        return 1

    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)

    distances = [float('inf')] * n
    distances[source] = 0

    queue = [(source, 1)]
    while queue:
        current_node, path_length = queue.pop(0)

        if current_node == target:
            return path_length

        for neighbor in graph[current_node]:
            if distances[neighbor] > path_length + 1:
                distances[neighbor] = path_length + 1
                queue.append((neighbor, path_length + 1))

    return 0
