from collections import defaultdict

def count_shortest_paths(n: int, edges: list[tuple[int, int]], source: int, target: int) -> int:
    if source == target:
        return 1

    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)

    def bfs(start):
        queue = [(start, 1)]
        visited = set([start])
        while queue:
            node, path_length = queue.pop(0)
            if node == target:
                return path_length
            for neighbor in graph[node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append((neighbor, path_length + 1))
        return float('inf')

    min_path_length = bfs(source)
    if min_path_length == float('inf'):
        return 0
    else:
        return n - min_path_length + 1
