from collections import deque

def shortest_path_one_break(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Find starting and ending positions
    start, end = None, None
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    if start is None or end is None:
        return -1

    # Initialize BFS queue with starting position and break count
    queue = deque([(start, 0)])
    visited = set([start])

    while queue:
        current, breaks = queue.popleft()

        if current == end:
            return breaks

        for dx, dy in directions:
            nx, ny = current[0] + dx, current[1] + dy

            if 0 <= nx < rows and 0 <= ny < cols:
                if grid[nx][ny] == '.' and (nx, ny) not in visited:
                    visited.add((nx, ny))
                    queue.append(((nx, ny), breaks))
                elif grid[nx][ny] == '#' and breaks < 1:
                    visited.add((nx, ny))
                    queue.append(((nx, ny), breaks + 1))

    return -1
