            if 0 <= nx < rows and 0 <= ny < cols:
                if grid[nx][ny] == '#':
                    if has_break:
                        continue
                    else:
                        queue.append(((nx, ny), steps + 1, True))
                else:
                    queue.append(((nx, ny), steps + 1, has_break))

    return -1
