from collections import defaultdict
from heapq import heappush, heappop

def count_shortest_paths(n: int, edges: list[tuple[int, int]], source: int, target: int) -> int:
    if source == target:
        return 1

    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)

    distances = [float('inf')] * n
    distances[source] = 0
    heap = [(0, source)]

    while heap:
        current_distance, current_node = heappop(heap)

        if current_distance > distances[current_node]:
            continue

        if current_node == target:
            break

        for neighbor in graph[current_node]:
            distance = current_distance + 1
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heappush(heap, (distance, neighbor))

    if distances[target] == float('inf'):
        return 0

    # Count all paths of length equal to the shortest path length
    count = 0
    queue = [(distances[target], target)]
    visited = set()

    while queue:
        current_distance, current_node = queue.pop(0)

        if current_node in visited:
            continue

        visited.add(current_node)

        if current_distance == 0:
            count += 1
            continue

        for neighbor in graph[current_node]:
            if distances[neighbor] == current_distance - 1:
                queue.append((current_distance - 1, neighbor))

    return count
