from typing import List, Tuple

def count_queens(n: int, blocked: List[Tuple[int, int]]) -> int:
    if n == 0:
        return 1

    blocked_set = set(blocked)

    def is_safe(row: int, col: int) -> bool:
        for r, c in blocked_set:
            if abs(r - row) == abs(c - col) or r == row or c == col:
                return False
        return True

    def backtrack(row: int) -> int:
        if row == n:
            return 1

        count = 0
        for col in range(n):
            if is_safe(row, col):
                blocked_set.add((row, col))
                count += backtrack(row + 1)
                blocked_set.remove((row, col))

        return count

    return backtrack(0)

# Example usage:
# print(count_queens(4, [(0, 2), (1, 3)]))
```

