def count_queens(n: int, blocked: List[Tuple[int, int]]) -> int:
    if n == 0:
        return 1

    blocked_set = set(blocked)

    def is_valid_position(row: int, col: int) -> bool:
        for i in range(n):
            if (i, col) in blocked_set or (row, i) in blocked_set:
                return False
        # Check diagonals
        for i in range(1, min(n - row, n - col)):
            if (row + i, col + i) in blocked_set:
                return False
        for i in range(1, min(row, col) + 1):
