import os
import subprocess

def make_tar(directory: str, archive_path: str) -> str:
    # Ensure the directory exists
    if not os.path.exists(directory):
        raise FileNotFoundError(f"Directory {directory} does not exist.")

    # Ensure the archive path is in the directory
    if not archive_path.startswith(directory):
        raise ValueError("Archive path must be inside the specified directory.")

    # Use subprocess to run the tar command securely
    try:
        subprocess.run(
            ["tar", "-czf", archive_path, directory],
            check=True,
            capture_output=True,
            text=True
        )
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Failed to create tar archive: {e.stderr}")

    return archive_path

