import re

def identifier_to_snake(name: str) -> str:
    # Remove underscores and hyphens
    name = re.sub(r'_|-', '', name)

    # Split the name into words
    words = name.split()

    # Convert each word to snake case
    snake_case_words = []
    for word in words:
        if word.islower():
            snake_case_words.append(word)
        else:
            snake_case_word = ''
            for i, char in enumerate(word):
                if i % 2 == 0:
                    snake_case_word += char.lower()
                else:
                    snake_case_word += char.upper()
            snake_case_words.append(snake_case_word)

    # Join the snake case words with underscores
    return '_'.join(snake_case_words)

# Example usage:
print(identifier_to_snake("HelloWorld"))  # Output: hello_world
print(identifier_to_snake("This_is_a_test"))  # Output: this_is_a_test
print(identifier_to_snake("123abc_def"))  # Output: 123abc_def
print(identifier_to_snake("aBcDeF"))  # Output: abc_def

