import re

def evaluate_expression(expression: str) -> float:
    # Check if the expression is empty or contains invalid characters
    if not expression or not re.match(r'^[\d\.\+\-\*/\(\)\s]+$', expression):
        raise ValueError("Invalid expression")

    # Define the precedence of operators
    precedence = {
        '+': 1,
        '-': 1,
        '*': 2,
        '/': 2,
        '**': 3,
        '-': 4  # Unary minus
    }

    def apply_operator(operators, values):
        operator = operators.pop()
        right = values.pop()
        left = values.pop()
        if operator == '+':
            values.append(left + right)
        elif operator == '-':
            values.append(left - right)
        elif operator == '*':
            values.append(left * right)
        elif operator == '/':
            if right == 0:
                raise ZeroDivisionError("Division by zero")
            values.append(left / right)
        elif operator == '**':
            values.append(left ** right)
        elif operator == '-':
            values.append(-left)

    def greater_precedence(op1, op2):
        return precedence[op1] > precedence[op2]

    def infix_to_postfix(expression: str) -> list:
        operators = []
        postfix = []
        i = 0
        while i < len(expression):
            char = expression[i]
            if char.isdigit() or char == '.':
                j = i
                while j < len(expression) and (expression[j].isdigit() or expression[j] == '.'):
                    j += 1
                postfix.append(float(expression[i:j]))
                i = j - 1
            elif char in precedence:
                while (operators and operators[-1] != '(' and
                       greater_precedence(operators[-1], char)):
                    apply_operator(operators, postfix)
                operators.append(char)
            elif char == '(':
                operators.append(char)
            elif char == ')':
                while operators and operators[-1] != '(':
                    apply_operator(operators, postfix)
                if operators and operators[-1] == '(':
                    operators.pop()
            i += 1
        while operators:
            apply_operator(operators, postfix)
        return postfix

    try:
        postfix = infix_to_postfix(expression)
        return postfix[0]
    except ZeroDivisionError as e:
        raise ZeroDivisionError("Division by zero") from e
    except Exception as e:
        raise ValueError("Invalid expression") from e
