from collections import deque

def shortest_path_one_break(grid: list[str]) -> int:
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    rows, cols = len(grid), len(grid[0])

    # Find starting and ending positions
    start, end = None, None
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    if start is None or end is None:
        return -1

    # BFS to find the shortest path with one break
    queue = deque([(start, 0, False)])  # (position, steps, has_break)
    visited = set()

    while queue:
        pos, steps, has_break = queue.popleft()

        if pos == end:
            return steps

        if pos in visited:
            continue
        visited.add(pos)

        for dx, dy in directions:
            nx, ny = pos[0] + dx, pos[1] + dy
            if 0 <= nx < rows and 0 <= ny < cols:
                if grid[nx][ny] == '#':
                    continue
                if has_break:
                    queue.append(((nx, ny), steps + 1, True))
                else:
                    queue.append(((nx, ny), steps + 1, False))

    return -1
