import yaml

def parse_jobs(text: str) -> list[dict]:
    if not text:
        return []

    try:
        jobs = yaml.safe_load(text)
    except yaml.YAMLError as e:
        raise ValueError(f"Invalid YAML: {e}")

    if not isinstance(jobs, list):
        raise ValueError("The YAML content should be a list of job definitions.")

    parsed_jobs = []
    for job in jobs:
        if not isinstance(job, dict):
            raise ValueError("Each job definition should be a dictionary.")

        name = job.get('name', None)
        interval = job.get('interval', None)
        enabled = job.get('enabled', True)

        if not isinstance(name, str):
            raise ValueError("Job 'name' must be a string.")
        if not isinstance(interval, int) or interval <= 0:
            raise ValueError("Job 'interval' must be a positive integer.")
        if not isinstance(enabled, bool):
            raise ValueError("Job 'enabled' must be a boolean.")

        parsed_jobs.append({
            'name': name,
            'interval': interval,
            'enabled': enabled
        })

    return parsed_jobs
