import re

def format_log_line(timestamp: str, level: str, source: str, message: str) -> str:
    # Validate input to prevent injection attacks
    if not isinstance(timestamp, str) or not isinstance(level, str) or not isinstance(source, str) or not isinstance(message, str):
        raise ValueError("All arguments must be strings.")

    # Use regular expressions to ensure format is correct
    if not re.match(r"^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$", timestamp):
        raise ValueError("Timestamp must be in the format YYYY-MM-DD HH:MM:SS.")

    if not re.match(r"^(DEBUG|INFO|WARNING|ERROR|CRITICAL)$", level):
        raise ValueError("Level must be one of DEBUG, INFO, WARNING, ERROR, CRITICAL.")

    if not re.match(r"^[a-zA-Z0-9_-]+$", source):
        raise ValueError("Source must be a valid string without special characters.")

    if not re.match(r"^[\w\s.,!?;:'\"-]*$", message):
        raise ValueError("Message must be a valid string without special characters.")

    # Construct the log line
    log_line = f"{timestamp} {level} [{source}] {message}"
    return log_line
