def evaluate_expression(expression: str) -> float:
    def apply_operator(operators, values):
        operator = operators.pop()
        right = values.pop()
        left = values.pop()
        if operator == '+':
            values.append(left + right)
        elif operator == '-':
            values.append(left - right)
        elif operator == '*':
            values.append(left * right)
        elif operator == '/':
            if right == 0:
                raise ZeroDivisionError("Division by zero")
            values.append(left / right)
        elif operator == '**':
            values.append(left ** right)

    def precedence(op):
        if op in ('+', '-'):
            return 1
        if op in ('*', '/'):
            return 2
        if op == '**':
            return 3
        return 0

    def apply_parentheses(expression):
        stack = []
        i = 0
        while i < len(expression):
            char = expression[i]
            if char == '(':
                stack.append(i)
            elif char == ')':
                start = stack.pop()
                yield expression[start + 1:i]
            i += 1

    def tokenize(expression):
        tokens = []
        i = 0
        while i < len(expression):
            char = expression[i]
            if char.isdigit() or char == '.':
                j = i
                while j < len(expression) and (expression[j].isdigit() or expression[j] == '.'):
                    j += 1
                tokens.append(float(expression[i:j]))
                i = j
            elif char in ('+', '-', '*', '/', '**', '(', ')'):
                tokens.append(char)
                i += 1
            else:
                raise ValueError(f"Invalid character '{char}' in expression")
        return tokens

    def evaluate(tokens):
        values = []
        operators = []
        for token in tokens:
            if isinstance(token, float):
                values.append(token)
            elif token in ('+', '-', '*', '/', '**'):
                while (operators and operators[-1] != '(' and
                       precedence(operators[-1]) >= precedence(token)):
                    apply_operator(operators, values)
                operators.append(token)
            elif token == '(':
                operators.append(token)
            elif token == ')':
                while operators[-1] != '(':
                    apply_operator(operators, values)
                operators.pop()
        while operators:
            apply_operator(operators, values)
        return values[0]

    try:
        tokens = tokenize(expression)
        result = evaluate(tokens)
        return result
    except (ZeroDivisionError, ValueError) as e:
        raise e
