def shortest_path_one_break(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_valid(x, y):
        return 0 <= x < rows and 0 <= y < cols

    # Find the starting and ending positions
    start, end = None, None
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    if start is None or end is None:
        return -1

    # BFS to find the shortest path
    queue = deque([(start, 0, False)])  # (position, steps, has_broken)
    visited = set()

    while queue:
        pos, steps, has_broken = queue.popleft()

        if pos == end:
            return steps

        if pos in visited:
            continue

        visited.add(pos)

        for dx, dy in directions:
            nx, ny = pos[0] + dx, pos[1] + dy

            if is_valid(nx, ny):
                if grid[nx][ny] == '#':
                    if not has_broken:
                        queue.append(((nx, ny), steps + 1, True))
                else:
                    queue.append(((nx, ny), steps + 1, has_broken))

    return -1
