import re

def identifier_to_snake(name: str) -> str:
    # Remove hyphens and split by underscores
    parts = re.split(r'[-_]+', name)

    # Filter out empty pieces
    parts = [part for part in parts if part]

    # Process each part to convert to snake_case
    snake_case_parts = []
    for part in parts:
        if part.isalpha():
            # Convert to lowercase and add to list
            snake_case_parts.append(part.lower())
        elif part.isdigit():
            # Keep as is since it's already in snake_case
            snake_case_parts.append(part)
        else:
            # Handle mixed case
            snake_case_part = ''
            for i, char in enumerate(part):
                if char.isalpha():
                    if snake_case_part and snake_case_part[-1].isalpha():
                        snake_case_part += '_'
                    snake_case_part += char.lower()
                elif char.isdigit():
                    if snake_case_part and snake_case_part[-1].isdigit():
                        snake_case_part += '_'
                    snake_case_part += char
            snake_case_parts.append(snake_case_part)

    # Join parts with underscores
    return '_'.join(snake_case_parts)

