from collections import deque

def shortest_path_one_break(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Find the starting and ending positions
    start = None
    end = None
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    if start is None or end is None:
        return -1

    # Initialize the queue for BFS
    queue = deque([(start, 0, False)])  # (position, steps, has_broken)
    visited = set()

    while queue:
        pos, steps, has_broken = queue.popleft()

        # If we've reached the end, return the number of steps
        if pos == end:
            return steps

        # Check all four possible directions
        for dx, dy in directions:
            nx, ny = pos[0] + dx, pos[1] + dy

            # Check if the new position is within bounds
            if 0 <= nx < rows and 0 <= ny < cols:
                # If it's a wall and we haven't broken yet, try breaking it
                if grid[nx][ny] == '#' and not has_broken:
                    queue.append(((nx, ny), steps + 1, True))
                # If it's an empty cell, continue the path
                elif grid[nx][ny] == '.':
                    queue.append(((nx, ny), steps + 1, has_broken))

    # If we exhaust the queue without finding the end, return -1
    return -1
