            for op in ['*', '/', '**']:
                if op in tokens:
                    index = tokens.index(op)
                    left = parse_expression(tokens[:index])
                    right = parse_expression(tokens[index + 1:])
                    tokens = tokens[:index] + [eval(f"{left} {op} {right}")] + tokens[index + 2:]
                    break
            else:
