import hashlib

def hash_pin(pin: str) -> str:
    if len(pin) < 4 or len(pin) > 6:
        raise ValueError("PIN must be between 4 and 6 digits.")

    # Use SHA-256 for hashing
    hashed = hashlib.sha256(pin.encode()).hexdigest()
    return hashed

def check_pin(pin: str, stored: str) -> bool:
    if len(pin) != len(stored):
        return False

    # Re-hash the input pin to compare with the stored hash
    rehashed = hash_pin(pin)
    return rehashed == stored

