def count_items(xml_text: str) -> int:
    try:
        # Parse the XML text
        root = ET.fromstring(xml_text)

        # Define a function to recursively count items
        def count_items_in_element(element):
            count = 0
            for child in element:
                if child.tag == 'item':
                    count += 1
                count += count_items_in_element(child)
            return count

        # Start counting from the root element
        return count_items_in_element(root)

    except ET.ParseError:
        # Handle invalid XML
        return 0
