from datetime import datetime, timedelta

def add_business_days(start: str, n: int, holidays: list[str]) -> str:
    # Convert the start date string to a datetime object
    start_date = datetime.strptime(start, "%Y-%m-%d")

    # Define a function to check if a day is a business day
    def is_business_day(day):
        return day.weekday() < 5 and day.strftime("%Y-%m-%d") not in holidays

    # Calculate the number of days to add or subtract
    total_days = n

    # Adjust for holidays
    while total_days > 0:
        start_date += timedelta(days=1)
        if is_business_day(start_date):
            total_days -= 1

    while total_days < 0:
        start_date -= timedelta(days=1)
        if is_business_day(start_date):
            total_days += 1

    # Format the result as a string
    return start_date.strftime("%Y-%m-%d")

# Example usage:
print(add_business_days("2024-03-01", 1, []))  # Output: "2024-03-04"

