import re

def decode_runs(encoded: str) -> str:
    decoded = []
    i = 0
    while i < len(encoded):
        if encoded[i] == '\\':
            decoded.append('\\')
            i += 1
        elif encoded[i] == '~':
            n = int(encoded[i+1:i+3])
            decoded.extend([encoded[i+2]] * n)
            i += 3
        else:
            decoded.append(encoded[i])
            i += 1
    return ''.join(decoded)

