from typing import List

def pack_bins(sizes: List[int], capacity: int) -> List[List[int]]:
    if not sizes:
        return []

    bins = []
    current_bin = []
    current_capacity = 0

    for size in sorted(sizes, reverse=True):
        if size > capacity:
            raise ValueError("Item size exceeds bin capacity")

        if current_capacity + size <= capacity:
            current_bin.append(size)
            current_capacity += size
        else:
            bins.append(current_bin)
            current_bin = [size]
