from math import gcd
from functools import reduce

def solve_congruences(congruences: list[tuple[int, int]]) -> tuple[int, int] | None:
    if not congruences:
        return (0, 1)

    def lcm(a, b):
        return abs(a * b) // gcd(a, b)

    L = reduce(lcm, [m for _, m in congruences])
    solutions = []

    for r, m in congruences:
        # Normalize r modulo m
        r %= m
        # Find the smallest positive solution for this congruence
        for x in range(m):
            if (x + r) % m == 0:
                solutions.append(x)
                break

    if not solutions:
        return None

    # Find the smallest solution that satisfies all congruences
    x = solutions[0]
    for sol in solutions[1:]:
        x += L
        while x % sol != 0:
            x += L

    return (x, L)
