from math import gcd
from functools import reduce

def lcm(a, b):
    return abs(a * b) // gcd(a, b)

def solve_congruences(congruences: list[tuple[int, int]]) -> tuple[int, int] | None:
    if not congruences:
        return (0, 1)

    moduli = [m for _, m in congruences]
    if not all(gcd(m, n) == 1 for m, n in zip(moduli, moduli[1:])):
        return None

    L = reduce(lcm, moduli)
    solutions = []

    for r, m in congruences:
        k = L // m
        x = (r * k) % L
        solutions.append(x)

    if len(set(solutions)) != len(solutions):
        return None

    return (min(solutions), L)
