import yaml

def parse_jobs(text: str) -> list[dict]:
    if not text:
        return []

    try:
        jobs = yaml.safe_load(text)
    except yaml.YAMLError as e:
        raise ValueError(f"Invalid YAML format: {e}")

    if not isinstance(jobs, list):
        raise ValueError("Jobs must be a list of dictionaries")

    parsed_jobs = []
    for job in jobs:
        if not isinstance(job, dict):
            raise ValueError("Each job must be a dictionary")

        name = job.get('name', None)
        interval = job.get('interval', None)
        enabled = job.get('enabled', True)

        if name is None or interval is None:
            raise ValueError("Each job must have 'name' and 'interval' keys")

        if not isinstance(name, str):
            raise ValueError("'name' must be a string")
        if not isinstance(interval, int):
            raise ValueError("'interval' must be an integer")
        if not isinstance(enabled, bool):
            raise ValueError("'enabled' must be a boolean")

