import re

def evaluate_expression(expression: str) -> float:
    # Regular expression to match valid tokens in the expression
    token_pattern = re.compile(r'\b\d+\.\d+|\b\d+|\+|-|\*|/|\*\*|\(|\)|\s')

    # Tokenize the input expression
    tokens = token_pattern.findall(expression)

    # Stack to hold operands
    operand_stack = []

    # Stack to hold operators
    operator_stack = []

    # Precedence of operators
    precedence = {'+': 1, '-': 1, '*': 2, '/': 2, '**': 3}

    # Iterate over each token in the expression
    for token in tokens:
        if token.isdigit() or '.' in token:
            # Push operand onto the stack
            operand_stack.append(float(token))
        elif token in precedence:
            # Process operators in the stack
            while (operator_stack and operator_stack[-1] != '(' and
                   precedence[operator_stack[-1]] >= precedence[token]):
                right = operand_stack.pop()
                left = operand_stack.pop()
                operator = operator_stack.pop()
                if operator == '+':
                    operand_stack.append(left + right)
                elif operator == '-':
                    operand_stack.append(left - right)
                elif operator == '*':
                    operand_stack.append(left * right)
                elif operator == '/':
                    if right == 0:
                        raise ZeroDivisionError("Division by zero")
                    operand_stack.append(left / right)
                elif operator == '**':
                    operand_stack.append(left ** right)
            # Push the current operator onto the stack
            operator_stack.append(token)
        elif token == '(':
            # Push opening parenthesis onto the stack
            operator_stack.append(token)
        elif token == ')':
            # Process operators until an opening parenthesis is encountered
            while operator_stack and operator_stack[-1] != '(':
                right = operand_stack.pop()
                left = operand_stack.pop()
                operator = operator_stack.pop()
                if operator == '+':
