def shortest_path_one_break(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Find starting and ending positions
    start, end = None, None
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    if start is None or end is None:
        return -1

    # Initialize BFS queue with start position and break count
    queue = deque([(start, 0)])
    visited = set([start])

    while queue:
        current, breaks = queue.popleft()

        if current == end:
            return breaks

        for dr, dc in directions:
            new_r, new_c = current[0] + dr, current[1] + dc

            if 0 <= new_r < rows and 0 <= new_c < cols:
                if grid[new_r][new_c] == '#':
                    if breaks < 1:
                        continue
                    new_breaks = breaks - 1
                else:
                    new_breaks = breaks

                if (new_r, new_c, new_breaks) not in visited:
                    visited.add((new_r, new_c, new_breaks))
                    queue.append(((new_r, new_c), new_breaks))

    return -1
