from collections import deque

def shortest_path_one_break(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Find the starting and ending positions
    start, end = None, None
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    if start is None or end is None:
        return -1

    # Initialize the queue with the starting position and the number of breaks used
    queue = deque([(start, 0)])
    visited = set([start])

    while queue:
        current, breaks_used = queue.popleft()

        # If we reach the end, return the number of breaks used
        if current == end:
            return breaks_used

        # Explore all four possible directions
        for dx, dy in directions:
            nx, ny = current[0] + dx, current[1] + dy

            # Check if the new position is within bounds
            if 0 <= nx < rows and 0 <= ny < cols:
                # If the cell is empty, add it to the queue
                if grid[nx][ny] == '.':
                    queue.append(((nx, ny), breaks_used))
                # If the cell is a wall and we haven't used any breaks yet, add it to the queue
                elif grid[nx][ny] == '#' and breaks_used == 0:
                    queue.append(((nx, ny), breaks_used + 1))

    # If we exhaust the queue without reaching the end, return -1
    return -1
