def parse_jobs(text: str) -> list[dict]:
    if not text:
        return []

    try:
        jobs = yaml.safe_load(text)
        if not isinstance(jobs, list):
            raise ValueError("The input is not a valid list of jobs.")

        parsed_jobs = []
        for job in jobs:
            if not isinstance(job, dict):
                raise ValueError(f"Job {job} is not a valid dictionary.")

            name = job.get('name', None)
            interval = job.get('interval', None)
            enabled = job.get('enabled', True)

            if name is None or interval is None:
                raise ValueError(f"Job {job} is missing required fields 'name' and 'interval'.")

            if not isinstance(name, str):
                raise ValueError(f"Job {job} has an invalid 'name' field.")

            if not isinstance(interval, int):
                raise ValueError(f"Job {job} has an invalid 'interval' field.")

            parsed_jobs.append({
                'name': name,
                'interval': interval,
                'enabled': enabled
            })

        return parsed_jobs

    except yaml.YAMLError as e:
        raise ValueError(f"Error parsing YAML: {e}")
