from typing import List, Tuple

def seating_arrangements(guests: List[str], conflicts: List[Tuple[str, str]]) -> List[List[str]]:
    if not guests:
        return [[]]

    # Create a graph to represent conflicts
    graph = {guest: set() for guest in guests}
    for a, b in conflicts:
        graph[a].add(b)
        graph[b].add(a)

    def dfs(guest, path):
        if guest in path:
            return False
        path.append(guest)
        for neighbor in graph[guest]:
            if not dfs(neighbor, path):
                return False
        return True

    result = []
    for guest in guests:
        if dfs(guest, []):
            result.append([guest])

    # Sort each arrangement by name
    for arrangement in result:
        arrangement.sort()

    return result
