def fetch_target_allowed(url: str, allowed_hosts: list[str]) -> bool:
    # Check if the URL starts with http or https
    if not re.match(r'^https?://', url):
        return False

    # Extract the host from the URL
    host_match = re.search(r'^(https?://)?([^/]+)', url)
    if not host_match:
        return False

    host = host_match.group(2)

    # Convert host to lowercase and remove trailing '.'
    host_lower = host.lower()
    if host_lower.endswith('.'):
        host_lower = host_lower[:-1]

    # Check if the host is in the allowed hosts list
    for allowed_host in allowed_hosts:
        allowed_host_lower = allowed_host.lower()
        if allowed_host_lower == host_lower:
            return True

    return False

