                result_date += timedelta(days=1)
        else:
            # Retroceder hasta encontrar un día hábil
            while not is_business_day(result_date):
                result_date -= timedelta(days=1)

    # Devolver la fecha resultante en el formato original
    return result_date.strftime("%Y-%m-%d")

