from datetime import datetime, timedelta

def add_business_days(start: str, n: int, holidays: list[str]) -> str:
    # Convertir la fecha de inicio a un objeto datetime
    start_date = datetime.strptime(start, "%Y-%m-%d")

    # Crear un conjunto de fechas de feriado para búsqueda rápida
    holiday_set = set(holiday for holiday in holidays)

    # Función para determinar si un día es hábil
    def is_business_day(date):
        return date.weekday() < 5 and date not in holiday_set

    # Calcular la nueva fecha
    new_date = start_date + timedelta(days=n)

    # Si n es positivo, avanzar hasta el siguiente día hábil
    if n > 0:
        while not is_business_day(new_date):
            new_date += timedelta(days=1)
    # Si n es negativo, retroceder hasta el anterior día hábil
    elif n < 0:
        while not is_business_day(new_date):
            new_date -= timedelta(days=1)

    # Devolver la nueva fecha formateada
    return new_date.strftime("%Y-%m-%d")

