def convert_base(number: str, from_base: int, to_base: int) -> str:
    if not number and (from_base < 2 or from_base > 36) or (to_base < 2 or to_base > 36):
        raise ValueError("Invalid input")

    is_negative = number.startswith('-')
    number = number.lstrip('-')

    if not number:
        return '-' if is_negative else '0'

    digits = "0123456789abcdefghijklmnopqrstuvwxyz"
    if from_base < 10:
        digits = digits[:from_base]

    try:
        num = int(number, from_base)
    except ValueError:
        raise ValueError("Invalid number for given base")

    if num == 0:
        return '0'

    result = ""
    while num > 0:
        result = digits[num % to_base] + result
        num //= to_base

    return '-' + result if is_negative else result
