def convert_base(number: str, from_base: int, to_base: int) -> str:
    if from_base < 2 or from_base > 36 or to_base < 2 or to_base > 36:
        raise ValueError("Base must be between 2 and 36.")

    if not number:
        raise ValueError("Input number cannot be empty.")

    is_negative = number.startswith('-')
    number = number.lstrip('-')

    if not all(c.isdigit() or 'a' <= c.lower() <= 'z' for c in number):
        raise ValueError("Invalid characters in input number.")

    if is_negative:
        number = '-' + number

    digits = "0123456789abcdefghijklmnopqrstuvwxyz"

    if from_base == 10:
        num = int(number)
    else:
        num = 0
        for i, char in enumerate(reversed(number)):
            if 'a' <= char.lower() <= 'z':
                value = digits.index(char.lower()) + 10
            else:
                value = int(char)
            num += value * (from_base ** i)

    if num == 0:
        return "0"

    result = ""
    while num > 0:
        remainder = num % to_base
        result = digits[remainder] + result
        num //= to_base

    return "-" + result if is_negative else result
