def add_business_days(start: str, n: int, holidays: list[str]) -> str:
    start_date = datetime.strptime(start, "%Y-%m-%d")

    def is_weekday(day):
        return day.weekday() < 5  # Monday is 0, Sunday is 6

    def is_holiday(day):
        return day.strftime("%Y-%m-%d") in holidays

    while n != 0:
        if n > 0:
            start_date += timedelta(days=1)
            while not is_weekday(start_date) or is_holiday(start_date):
                start_date += timedelta(days=1)
        else:
            start_date -= timedelta(days=1)
            while not is_weekday(start_date) or is_holiday(start_date):
                start_date -= timedelta(days=1)

        n -= 1

    return start_date.strftime("%Y-%m-%d")

