import re

def fetch_target_allowed(url: str, allowed_hosts: list[str]) -> bool:
    # Check if the URL starts with http or https
    if not url.startswith(('http://', 'https://')):
        return False

    # Extract the host from the URL
    host = re.search(r'//([^/]+)', url).group(1)

    # Convert both the host and allowed hosts to lowercase
    host_lower = host.lower()
    allowed_hosts_lower = [host.lower() for host in allowed_hosts]

    # Check if the host is in the allowed hosts list
    for allowed_host in allowed_hosts_lower:
        if host_lower == allowed_host:
            return True
        elif allowed_host.endswith('.'):
            if host_lower.startswith(allowed_host[:-1]):
                return True

    return False
