def seating_arrangements(guests: List[str], conflicts: List[Tuple[str, str]]) -> List[List[str]]:
    if not guests:
        return [[]]

    def is_valid(arrangement):
        for i in range(len(arrangement)):
            for j in range(i + 1, len(arrangement)):
                if (arrangement[i], arrangement[j]) in conflicts or (arrangement[j], arrangement[i]) in conflicts:
                    return False
        return True

    def backtrack(start, path):
        if start == len(guests):
            if is_valid(path):
                result.append(path[:])
            return

        for i in range(start, len(guests)):
            path.append(guests[i])
            backtrack(i + 1, path)
            path.pop()

    result = []
    backtrack(0, [])
    result.sort(key=lambda x: ' '.join(x))
    return result
