def add_business_days(start: str, n: int, holidays: list[str]) -> str:
    # Convert the start date string to a datetime object
    start_date = datetime.strptime(start, "%Y-%m-%d")

    # Define a set of holidays for quick lookup
    holiday_set = {datetime.strptime(date, "%Y-%m-%d") for date in holidays}

    # Initialize the current date as the start date
    current_date = start_date

    # Determine the direction of movement based on n
    if n > 0:
        while n > 0:
            current_date += timedelta(days=1)
            if current_date.weekday() < 5 and current_date not in holiday_set:
                n -= 1
    elif n < 0:
        while n < 0:
            current_date -= timedelta(days=1)
            if current_date.weekday() < 5 and current_date not in holiday_set:
                n += 1

    # Format the resulting date back to a string
    return current_date.strftime("%Y-%m-%d")

