import re

def matches_filter(expression: str, record: dict) -> bool:
    # Define a regular expression pattern to match valid keys in the dictionary
    key_pattern = re.compile(r'^[a-zA-Z_][a-zA-Z0-9_]*$')

    # Split the expression into tokens
    tokens = expression.split()

    # Validate the expression syntax
    if len(tokens) % 2 != 1 or not all(token in record for token in tokens[::2]):
        raise ValueError("Invalid filter expression")

    # Evaluate the expression
    stack = []
    for i in range(0, len(tokens), 2):
        left = tokens[i]
        operator = tokens[i + 1]
        right = tokens[i + 2]

        if not key_pattern.match(left):
            raise ValueError(f"Invalid key: {left}")

        if operator not in ('<', '<=', '>', '>=', '==', '!=', 'and', 'or', 'not'):
            raise ValueError(f"Invalid operator: {operator}")

        if operator == 'and':
            stack.append((left, operator, right))
        elif operator == 'or':
            stack.append((left, operator, right))
        elif operator == 'not':
            stack.append((left, operator, None))
        else:
            try:
                left_value = record[left]
                right_value = eval(right)
            except (KeyError, NameError, SyntaxError, TypeError) as e:
                raise ValueError(f"Error evaluating expression: {e}")

            if operator == '<':
                stack.append((left_value, operator, right_value))
            elif operator == '<=':
                stack.append((left_value, operator, right_value))
            elif operator == '>':
                stack.append((left_value, operator, right_value))
            elif operator == '>=':
                stack.append((left_value, operator, right_value))
            elif operator == '==':
                stack.append((left_value, operator, right_value))
            elif operator == '!=':
                stack.append((left_value, operator, right_value))

    while len(stack) > 1:
        left, operator, right = stack.pop()
        if operator == 'and':
            if not eval(f"{left} {operator} {right}"):
                return False
        elif operator == 'or':
            if eval(f"{left} {operator} {right}"):
                return True
        elif operator == 'not':
            if not eval(f"{left} {operator}"):
                return True

    return eval(f"{stack[0]}")

# Example usage:
