        if start == len(guests):
            if is_valid(current):
                result.append(current[:])
            return

        for guest in guests[start:]:
            current.append(guest)
            backtrack(start + 1, current)
            current.pop()

    result = []
    backtrack(0, [])
    result.sort()
    return result
