from urllib.parse import urlparse

def fetch_target_allowed(url: str, allowed_hosts: list[str]) -> bool:
    parsed_url = urlparse(url)

    # Check if the scheme is either http or https
    if parsed_url.scheme.lower() not in ['http', 'https']:
        return False

    # Check if there is a user before the host
    if '@' in parsed_url.netloc:
        return False

    # Extract the hostname and remove any trailing dot
    hostname = parsed_url.hostname.lower().rstrip('.')

    # Check if the hostname is in the allowed hosts list
    for allowed_host in allowed_hosts:
        if hostname == allowed_host.lower():
            return True

    return False

