from typing import List

def min_slides(grid: List[str]) -> int:
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    rows, cols = len(grid), len(grid[0])

    def is_valid(x, y):
        return 0 <= x < rows and 0 <= y < cols

    def bfs(start_x, start_y):
        queue = [(start_x, start_y, 0)]
        visited = set()

        while queue:
            x, y, steps = queue.pop(0)

            if grid[x][y] == 'E':
                return steps

            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if is_valid(nx, ny) and grid[nx][ny] != '#' and (nx, ny) not in visited:
                    visited.add((nx, ny))
                    queue.append((nx, ny, steps + 1))

        return -1

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                return bfs(i, j)

    return -1
