from typing import List, Tuple

def seating_arrangements(guests: List[str], conflicts: List[Tuple[str, str]]) -> List[List[str]]:
    if not guests:
        return [[]]

    def is_valid(arrangement: List[str]) -> bool:
        for i in range(len(arrangement)):
            for j in range(i + 1, len(arrangement)):
                if (arrangement[i], arrangement[j]) in conflicts or (arrangement[j], arrangement[i]) in conflicts:
                    return False
        return True

    def backtrack(start: int, current: List[str]) -> None:
        if start == len(guests):
            if is_valid(current):
                arrangements.append(current[:])
            return

        for i in range(start, len(guests)):
            current.append(guests[i])
            backtrack(i + 1, current)
            current.pop()

    arrangements = []
    backtrack(0, [])
    arrangements.sort(key=lambda x: ' '.join(x))
    return arrangements
