def schedule_jobs(jobs: list[tuple[str, int, int]]) -> list[str]:
    # Sort jobs by profit in descending order
    jobs.sort(key=lambda x: x[2], reverse=True)

    # Initialize a list to keep track of assigned slots
    assigned_slots = [-1] * len(jobs)

    # Iterate over each job
    for i, (name, deadline, profit) in enumerate(jobs):
        # Try to find the latest available slot that is before the deadline
        for j in range(deadline - 1, -1, -1):
            if assigned_slots[j] == -1:
                assigned_slots[j] = i
                break

    # Collect the names of jobs assigned to each slot
    result = []
    for i, slot in enumerate(assigned_slots):
        if slot != -1:
            result.append(f"{jobs[slot][0]} {i + 1}")

