import re

def matches_filter(expression: str, record: dict) -> bool:
    # Check if the expression contains any invalid characters or names
    if not re.match(r'^[a-zA-Z0-9\s<>\!\&\|\(\)\[\]\{\}]+$', expression):
        raise ValueError("Invalid expression")

    # Define a helper function to evaluate a single condition
    def evaluate_condition(key, op, value):
        if key not in record:
            raise ValueError(f"Key '{key}' not found in record")

        val = record[key]
        if isinstance(val, str):
            val = val.strip()

        if op == '<':
            return val < value
        elif op == '<=':
            return val <= value
        elif op == '>':
            return val > value
        elif op == '>=':
            return val >= value
        elif op == '==':
            return val == value
        elif op == '!=':
            return val != value
        elif op == 'and':
            return evaluate_condition(key, '<=', value) and evaluate_condition(key, '>=', value)
        elif op == 'or':
            return evaluate_condition(key, '<=', value) or evaluate_condition(key, '>=', value)
        elif op == 'not':
            return not evaluate_condition(key, '<=', value)
        else:
            raise ValueError(f"Invalid operator '{op}'")

    # Split the expression into tokens
    tokens = re.findall(r'([a-zA-Z0-9\s]+|[<>=!&|()\[\]{}])', expression)

    # Evaluate the expression using a stack-based approach
    stack = []
    for token in tokens:
        if token.isdigit():
            stack.append(float(token))
        elif token.isalpha():
            stack.append(token)
        elif token in ['<', '<=', '>', '>=', '==', '!=']:
            right = stack.pop()
            left = stack.pop()
            stack.append(evaluate_condition(left, token, right))
        elif token in ['and', 'or', 'not']:
            right = stack.pop()
            left = stack.pop()
            stack.append(evaluate_condition(left, token, right))
        elif token in ['(', '[', '{']:
            stack.append(token)
        elif token in [')', ']', '}']:
            while stack and stack[-1] not in ['(', '[', '{']:
                right = stack.pop()
                left = stack.pop()
                stack.append(evaluate_condition(left, stack.pop(), right))
            if stack and stack[-1] in ['(', '[', '{']:
                raise ValueError("Mismatched brackets")
            stack.pop()

    # The final result should be a single boolean value
    if len(stack) != 1 or not isinstance(stack[0], bool):
        raise ValueError("Invalid expression")

    return stack[0]
