def teller_waits(arrivals: List[int], service_times: List[int], tellers: int) -> List[int]:
    if not arrivals or not service_times or tellers <= 0:
        return []

    n = len(arrivals)
    result = [0] * n
    queue = []
    current_time = 0

    for i in range(n):
        while queue and queue[0][0] <= current_time:
            _, j = heapq.heappop(queue)
            result[j] = current_time - arrivals[j]

        if tellers > 0:
            heapq.heappush(queue, (current_time + service_times[i], i))
            tellers -= 1
        else:
            result[i] = -1  # No available teller

        current_time += 1

    return result

