def rotate_rings(matrix: list[list[int]], k: int) -> list[list[int]]:
    if not matrix or not matrix[0]:
        return []

    n = len(matrix)
    if n == 1:
        return matrix

    # Normalize k to be within the range of the number of rings
    k = k % (2 * n - 2)
    if k == 0:
        return matrix

    def rotate_ring(start_row, start_col, end_row, end_col):
        nonlocal matrix
        if start_row == end_row or start_col == end_col:
            return

        # Collect elements in the ring
        ring_elements = []
        for i in range(start_row, end_row + 1):
            ring_elements.append(matrix[i][start_col])
        for j in range(start_col + 1, end_col + 1):
            ring_elements.append(matrix[end_row][j])
        for i in range(end_row - 1, start_row - 1, -1):
            ring_elements.append(matrix[i][end_col])
        for j in range(end_col - 1, start_col, -1):
            ring_elements.append(matrix[start_row][j])

        # Rotate the ring
        rotated_elements = ring_elements[-k:] + ring_elements[:-k]

        # Place the rotated elements back into the ring
        index = 0
        for i in range(start_row, end_row + 1):
            matrix[i][start_col] = rotated_elements[index]
            index += 1
        for j in range(start_col + 1, end_col + 1):
            matrix[end_row][j] = rotated_elements[index]
            index += 1
        for i in range(end_row - 1, start_row - 1, -1):
