            index += 1
        for j in range(end_col - 1, start_col, -1):
            matrix[start_row][j] = rotated_elements[index]
            index += 1

    # Rotate each ring
    for i in range(n // 2):
        rotate_ring(i, i, n - i - 1, n - i - 1)

    return matrix
