def convert_base(number: str, from_base: int, to_base: int) -> str:
    if not (2 <= from_base <= 36) or not (2 <= to_base <= 36):
        raise ValueError("Bases must be between 2 and 36.")

    if not number:
        return "0"

    is_negative = number.startswith('-')
    number = number[1:] if is_negative else number

    if not all(c in '0123456789abcdefghijklmnopqrstuvwxyz'[:from_base] for c in number):
        raise ValueError("Invalid characters in input number.")

    if from_base == 10:
        num = int(number)
    else:
        num = int(number, from_base)

    if num == 0:
        return "0"

    digits = []
    while num > 0:
        digits.append(chr(num % to_base + ord('a')))
        num //= to_base

    if is_negative:
        digits.append('-')

    return ''.join(reversed(digits))
