def convert_base(number: str, from_base: int, to_base: int) -> str:
    if from_base < 2 or from_base > 36 or to_base < 2 or to_base > 36:
        raise ValueError("Base must be between 2 and 36.")

    if not number:
        return "0"

    is_negative = number.startswith('-')
    number = number.lstrip('-')

    if not all(c in '0123456789abcdefghijklmnopqrstuvwxyz' for c in number):
        raise ValueError("Invalid characters in number.")

    if number == '0':
        return '0'

    # Convert from base from_base to decimal
    decimal_value = 0
    for i, digit in enumerate(reversed(number)):
        value = ord(digit.lower()) - ord('0') if digit.isdigit() else ord(digit.lower()) - ord('a') + 10
        decimal_value += value * (from_base ** i)

    if is_negative:
        decimal_value = -decimal_value

    # Convert from decimal to base to_base
    if decimal_value == 0:
        return '0'

    digits = []
    while decimal_value != 0:
        remainder = decimal_value % to_base
        digits.append(chr(remainder + ord('0')) if remainder < 10 else chr(remainder - 10 + ord('a')))
        decimal_value //= to_base

    return '-' + ''.join(reversed(digits)) if is_negative else ''.join(reversed(digits))

