import re

def matches_filter(expression: str, record: dict) -> bool:
    # Check if the expression contains any invalid characters or syntax
    if not re.match(r'^[a-zA-Z0-9\s<>\.\+\-\*/\(\)\[\]\{\}!&|]+$', expression):
        raise ValueError("Invalid expression")

    # Define a helper function to evaluate a single condition
    def evaluate_condition(key, op, value):
        if key not in record:
            raise ValueError(f"Key '{key}' not found in record")

        val = record[key]
        if isinstance(val, (int, float)):
            if op == '<':
                return val < value
            elif op == '<=':
                return val <= value
            elif op == '>':
                return val > value
            elif op == '>=':
                return val >= value
            elif op == '==':
                return val == value
            elif op == '!=':
                return val != value
        elif isinstance(val, str):
            if op == '==':
                return val == value
            elif op == '!=':
                return val != value
        else:
            raise ValueError(f"Unsupported type for key '{key}'")

    # Split the expression into tokens
    tokens = re.findall(r'[a-zA-Z0-9\s<>\.\+\-\*/\(\)\[\]\{\}!&|]+', expression)

    # Evaluate the expression using a stack-based approach
    stack = []
    for token in tokens:
        if token in ('and', 'or', 'not'):
            right = stack.pop()
            left = stack.pop()
            if token == 'and':
                stack.append(left and right)
            elif token == 'or':
                stack.append(left or right)
            elif token == 'not':
                stack.append(not left)
        elif token in ('<', '<=', '>', '>=', '==', '!='):
            right = stack.pop()
            left = stack.pop()
            stack.append(evaluate_condition(left, token, right))
        elif token in ('(', ')', '[', ']', '{', '}'):
            stack.append(token)
        else:
            stack.append(token)

    # The final result should be a single boolean value
    if len(stack) != 1 or not isinstance(stack[0], bool):
        raise ValueError("Invalid expression")

    return stack[0]
