from typing import *
from collections import defaultdict, deque

def cheapest_route(edges: list[tuple[str, str, int]], start: str, goal: str) -> tuple[int, list[str]] | None:
    if start == goal:
        return (0, [start])

    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))
        graph[v].append((u, w))

    min_cost = float('inf')
    best_path = None

    def bfs(start):
        nonlocal min_cost, best_path
        queue = deque([(start, 0, [start])])

        while queue:
            node, cost, path = queue.popleft()

            if node == goal:
                if cost < min_cost:
                    min_cost = cost
                    best_path = path
                continue

            for neighbor, weight in graph[node]:
                if neighbor not in path:
                    new_path = path + [neighbor]
                    new_cost = cost + weight
                    queue.append((neighbor, new_cost, new_path))

    bfs(start)

    return (min_cost, best_path) if best_path else None
