from typing import List

def teller_waits(arrivals: List[int], service_times: List[int], tellers: int) -> List[int]:
    if not arrivals or not service_times or tellers <= 0:
        return []

    wait_times = [0] * len(arrivals)
    free_tellers = list(range(tellers))
    current_time = 0

    for i, arrival in enumerate(arrivals):
        while free_tellers and current_time >= arrivals[free_tellers[0]]:
            free_tellers.pop(0)

        if free_tellers:
            teller_index = free_tellers.pop(0)
            wait_times[i] = current_time - arrivals[i]
            current_time += service_times[i]
            free_tellers.append(teller_index)
        else:
            # If no teller is free, wait until the next available teller
            wait_times[i] = current_time - arrivals[i]
            current_time += service_times[i]

    return wait_times

