def rotate_rings(matrix: list[list[int]], k: int) -> list[list[int]]:
    if not matrix or not matrix[0]:
        return []

    n = len(matrix)
    if n == 1:
        return matrix

    # Normalize k to be within the bounds of the matrix size
    k = k % (2 * n - 2)

    if k == 0:
        return matrix

    result = [[0] * n for _ in range(n)]

    for i in range(n):
        start = i
        end = n - i - 1
        step = 1 if k > 0 else -1

        for j in range(start, end + 1):
            if k > 0:
                result[i][j] = matrix[j][start]
            else:
                result[i][j] = matrix[end][j]

        k += step

    return result
