import math

def evaluate_formula(formula: str, x: float) -> float:
    def parse_expression(tokens):
        if not tokens:
            return None

        token = tokens.pop(0)

        if token == '(':
            expr = parse_expression(tokens)
            if tokens.pop(0) != ')':
                raise ValueError("Unmatched parenthesis")
            return expr

        if token.isdigit() or '.' in token:
            try:
                return float(token)
            except ValueError:
                raise ValueError(f"Invalid number: {token}")

        if token in ['+', '-', '*', '/', '**', 'sqrt', 'abs', 'sin', 'cos']:
            if len(tokens) < 1:
                raise ValueError(f"Missing operand for operator: {token}")
            right = parse_expression(tokens)
            if token == '+':
                return left + right
            elif token == '-':
                return left - right
            elif token == '*':
                return left * right
            elif token == '/':
                if right == 0:
                    raise ZeroDivisionError("Division by zero")
                return left / right
            elif token == '**':
                return left ** right
            elif token == 'sqrt':
                if left < 0:
                    raise ValueError("Square root of negative number")
                return math.sqrt(left)
            elif token == 'abs':
                return abs(left)
            elif token == 'sin':
                return math.sin(math.radians(left))
            elif token == 'cos':
                return math.cos(math.radians(left))

        raise ValueError(f"Unknown token: {token}")

    tokens = formula.replace(' ', '').split()
    return parse_expression(tokens)

# Example usage:
