import re

def fetch_target_allowed(url: str, allowed_hosts: list[str]) -> bool:
    # Check if the URL starts with 'http' or 'https'
    if not re.match(r'^https?://', url):
        return False

    # Extract the host from the URL
    host = re.search(r'//([^/]+)', url).group(1)

    # Convert both the URL host and allowed hosts to lowercase
    url_host_lower = host.lower()
    allowed_hosts_lower = [host.lower() for host in allowed_hosts]

    # Check if the URL host is in the list of allowed hosts
    for allowed_host in allowed_hosts_lower:
        if url_host_lower == allowed_host:
            return True

    # Check for subdomain matches
    for allowed_host in allowed_hosts_lower:
        if url_host_lower.startswith(allowed_host + '.'):
            return True

    return False

