import re

def matches_filter(expression: str, record: dict) -> bool:
    # Define a regular expression pattern to match valid keys in the dictionary
    key_pattern = r'\b[a-zA-Z_][a-zA-Z0-9_]*\b'

    # Check if the expression contains only valid keys
    if not re.match(f'^({key_pattern}(?:\s*[\s*and\s*|\s*or\s*|\s*not\s*|\s*\(\s*{key_pattern}\s*\)\s*)*)$', expression):
        raise ValueError("Invalid filter expression")

    # Split the expression into parts based on logical operators
    parts = expression.split()

    # Initialize a list to store the evaluated parts
    evaluated_parts = []

    # Iterate over the parts and evaluate them
    i = 0
    while i < len(parts):
        part = parts[i]

        # If the part is a key, check if it exists in the record
        if re.match(key_pattern, part):
            if part not in record:
                raise KeyError(f"Key '{part}' not found in the record")
            evaluated_parts.append(record[part])
        else:
            # Evaluate the operator and its operands
            if part == 'and':
                evaluated_parts[-2] = evaluated_parts[-2] and evaluated_parts[-1]
            elif part == 'or':
                evaluated_parts[-2] = evaluated_parts[-2] or evaluated_parts[-1]
            elif part == 'not':
                evaluated_parts[-1] = not evaluated_parts[-1]
            else:
                # Assume the part is a comparison operator
                try:
                    left = evaluated_parts.pop()
                    right = evaluated_parts.pop()
                    if part == '<':
                        evaluated_parts.append(left < right)
                    elif part == '<=':
                        evaluated_parts.append(left <= right)
                    elif part == '>':
                        evaluated_parts.append(left > right)
                    elif part == '>=':
                        evaluated_parts.append(left >= right)
                    elif part == '==':
                        evaluated_parts.append(left == right)
                    elif part == '!=':
                        evaluated_parts.append(left != right)
                    else:
                        raise ValueError(f"Invalid operator '{part}'")
                except IndexError:
                    raise ValueError("Invalid filter expression")

        i += 1

    # The final result is the last evaluated part
    return evaluated_parts[0]
