def format_table(rows: list[list[str]], aligns: str) -> str:
    if not rows:
        return ""

    # Find the maximum width for each column
    max_widths = [max(len(row[i]) for row in rows) for i in range(len(rows[0]))]

    # Create the table string
    table_str = ""
    for row in rows:
        formatted_row = []
        for i, cell in enumerate(row):
            # Determine alignment and pad the cell
            if aligns[i] == 'l':
                formatted_cell = cell.ljust(max_widths[i])
            elif aligns[i] == 'r':
                formatted_cell = cell.rjust(max_widths[i])
            else:
                formatted_cell = cell.center(max_widths[i])
            formatted_row.append(formatted_cell)

        # Join the cells with a pipe and add a newline
        table_str += " | ".join(formatted_row) + "\n"

    return table_str
