    if not matrix or not matrix[0]:
        return []

    n = len(matrix)
    result = [[0] * n for _ in range(n)]

    for i in range(n):
        for j in range(n):
            # Calculate the new position after rotation
            new_i = (i + k) % n
            new_j = (j + k) % n

            # If k is negative, adjust the direction of rotation
            if k < 0:
                new_i = (i - k) % n
                new_j = (j - k) % n

            result[new_i][new_j] = matrix[i][j]

