        logging.error(f"Email: {email}, unknown: Failed to set password - {str(e)}")
        return False

    # Log the result of the password setting operation
    if success:
        logging.info(f"Email: {email}, updated: Password updated successfully")
    else:
        logging.info(f"Email: {email}, unknown: Password update failed")

    return success

