import re

def tokenize_code(source: str) -> list[tuple[str, str]]:
    tokens = []
    pattern = r'\b\d+(\.\d+)?\b|[a-zA-Z_][a-zA-Z0-9_]*|[+\-*/<>=(),]'

    for match in re.finditer(pattern, source):
        text = match.group()
        kind = None

        if text.isdigit() or (text.startswith('.') and text[1:].isdigit()):
            kind = "NUMBER"
        elif text.isidentifier():
            kind = "NAME"
        elif text in "+-*/<>=(),":
            kind = "OP"

        if kind is None:
            raise ValueError(f"Invalid character: {text}")

        tokens.append((kind, text))

    return tokens
