def format_table(rows: list[list[str]], aligns: str) -> str:
    if not rows:
        return ""

    # Find the maximum width for each column
    max_widths = [max(len(row[i]) for row in rows) for i in range(len(rows[0]))]

    # Determine the alignment for each column
    alignments = [aligns[i] if i < len(aligns) else 'c' for i in range(len(max_widths))]

    # Format each row
    formatted_rows = []
    for row in rows:
        formatted_row = []
        for i, cell in enumerate(row):
            width = max_widths[i]
            if alignments[i] == 'l':
                formatted_row.append(cell.ljust(width))
            elif alignments[i] == 'r':
                formatted_row.append(cell.rjust(width))
            else:  # alignments[i] == 'c'
                formatted_row.append(cell.center(width))
        formatted_rows.append(' | '.join(formatted_row))

    # Join all rows with newline characters
    return '\n'.join(formatted_rows)

