def free_slots(busy: list[tuple[int, int]], day_start: int, day_end: int, min_len: int) -> list[tuple[int, int]]:
    if day_start >= day_end:
        return []

    # Sort busy intervals by their start time
    busy.sort()

    # Initialize variables to track free slots
    free_slots = []
    current_free_start = day_start

    for start, end in busy:
        if start >= current_free_start:
            # If there's a gap between the current free slot and the busy interval
            if start - current_free_start >= min_len:
                free_slots.append((current_free_start, start))
            current_free_start = end

    # Check if there's a free slot at the end of the day
    if day_end - current_free_start >= min_len:
        free_slots.append((current_free_start, day_end))

    return free_slots

