def matches_filter(expression: str, record: dict) -> bool:
    # Parse the expression using ast.literal_eval to safely evaluate it
    try:
        parsed_expression = ast.parse(expression, mode='eval').body
    except (SyntaxError, ValueError):
        raise ValueError("Invalid expression")

    # Define a visitor class to handle the evaluation of the expression
    class ExpressionEvaluator(ast.NodeVisitor):
        def __init__(self, record):
            self.record = record

        def visit_Name(self, node):
            # Check if the name is a key in the record
            if node.id not in self.record:
                raise ValueError(f"Name '{node.id}' is not a key in the record")
            return self.record[node.id]

        def visit_Num(self, node):
            return node.n

        def visit_Str(self, node):
            return node.s

        def visit_Compare(self, node):
            left = self.visit(node.left)
            right = self.visit(node.comparators[0])
            op = node.ops[0]
            if op.__class__ == ast.Eq:
                return left == right
            elif op.__class__ == ast.NotEq:
                return left != right
            elif op.__class__ == ast.Lt:
                return left < right
            elif op.__class__ == ast.LtE:
                return left <= right
            elif op.__class__ == ast.Gt:
                return left > right
            elif op.__class__ == ast.GtE:
                return left >= right
            else:
                raise ValueError(f"Unsupported comparison operator: {op}")

        def visit_BinOp(self, node):
            left = self.visit(node.left)
            right = self.visit(node.right)
            op = node.op
            if op.__class__ == ast.Add:
                return left + right
            elif op.__class__ == ast.Sub:
                return left - right
            elif op.__class__ == ast.Mult:
                return left * right
            elif op.__class__ == ast.Div:
                return left / right
            elif op.__class__ == ast.FloorDiv:
                return left // right
            elif op.__class__ == ast.Mod:
                return left % right
            elif op.__class__ == ast.Pow:
                return left ** right
            else:
                raise ValueError(f"Unsupported binary operator: {op}")

        def visit_UnaryOp(self, node):
            operand = self.visit(node.operand)
            op = node.op
            if op.__class__ == ast.USub:
                return -operand
            elif op.__class__ == ast.UAdd:
                return operand
            elif op.__class__ == ast.Not:
                return not operand
            else:
                raise ValueError(f"Unsupported unary operator: {op}")

    # Create an instance of the evaluator and evaluate the expression
    evaluator = ExpressionEvaluator(record)
    return evaluator.visit(parsed_expression)

