import re

def matches_filter(expression: str, record: dict) -> bool:
    # Validate the expression to ensure it only uses allowed characters
    if not re.match(r'^[a-zA-Z0-9\s<>\.\+\-\*/\(\)\[\]\{\}!&|~]+$', expression):
        raise ValueError("Invalid expression")

    # Define a helper function to evaluate a single part of the expression
    def evaluate_part(part: str) -> bool:
        if part.isdigit():
            return int(part) in record.values()
        elif part.isalpha():
            if part in record:
                return record[part] is not None
            else:
                raise ValueError(f"Key '{part}' not found in record")
        elif part.startswith('"') and part.endswith('"'):
            return part[1:-1] == record.get(part[1:-1], "")
        elif part.startswith("'") and part.endswith("'"):
            return part[1:-1] == record.get(part[1:-1], "")
        elif part in ['<', '>', '<=', '>=', '==', '!=']:
            op = part
            left, right = expression.split(op, 1)
            left_value = evaluate_part(left.strip())
            right_value = evaluate_part(right.strip())
            if op == '<':
                return left_value < right_value
            elif op == '<=':
                return left_value <= right_value
            elif op == '>':
                return left_value > right_value
            elif op == '>=':
                return left_value >= right_value
            elif op == '==':
                return left_value == right_value
            elif op == '!=':
                return left_value != right_value
        elif part in ['and', 'or', 'not']:
            op = part
            left, right = expression.split(op, 1)
            left_value = evaluate_part(left.strip())
            right_value = evaluate_part(right.strip())
            if op == 'and':
                return left_value and right_value
            elif op == 'or':
                return left_value or right_value
            elif op == 'not':
                return not left_value
        elif part.startswith('(') and part.endswith(')'):
            return evaluate_part(part[1:-1])
        else:
            raise ValueError(f"Invalid part '{part}' in expression")

    # Evaluate the entire expression
    return evaluate_part(expression)

