import re

def tokenize_code(source: str) -> list[tuple[str, str]]:
    if not source.strip():
        return []

    tokens = []
    i = 0
    while i < len(source):
        # Skip whitespace and tabs
        if source[i].isspace():
            i += 1
            continue

        # Check for number
        if source[i].isdigit() or source[i] == '.':
            num_start = i
            while i < len(source) and (source[i].isdigit() or source[i] == '.'):
                i += 1
            num_text = source[num_start:i]
            if '.' in num_text:
                tokens.append(('NUMBER', num_text))
            else:
                tokens.append(('NUMBER', num_text + '0'))  # Ensure it's a valid float

        # Check for name
        elif source[i].isalpha() or source[i] == '_':
            name_start = i
            while i < len(source) and (source[i].isalnum() or source[i] == '_'):
                i += 1
            name_text = source[name_start:i]
            tokens.append(('NAME', name_text))

        # Check for operator
        elif source[i:i+2] in ['==', '!=', '<=', '>=', '+', '-', '*', '/', '<', '>', '=', '(', ')', ',']:
            op_start = i
            i += 2
            op_text = source[op_start:i]
            tokens.append(('OP', op_text))

        else:
            raise ValueError(f"Invalid character at position {i}: {source[i]}")

    return tokens
