import ast

def matches_filter(expression: str, record: dict) -> bool:
    # Parse the expression into an AST
    try:
        tree = ast.parse(expression, mode='eval')
    except SyntaxError:
        raise ValueError("Invalid expression")

    def evaluate(node):
        if isinstance(node, ast.Num):
            return node.n
        elif isinstance(node, ast.Str):
            return node.s
        elif isinstance(node, ast.Name):
            if node.id in record:
                return record[node.id]
            else:
                raise ValueError(f"Unknown key '{node.id}'")
        elif isinstance(node, ast.BinOp):
            left = evaluate(node.left)
            right = evaluate(node.right)
            if isinstance(node.op, ast.Add):
                return left + right
            elif isinstance(node.op, ast.Sub):
                return left - right
            elif isinstance(node.op, ast.Mult):
                return left * right
            elif isinstance(node.op, ast.Div):
                return left / right
            elif isinstance(node.op, ast.Pow):
                return left ** right
            elif isinstance(node.op, ast.BitXor):
                return left ^ right
            elif isinstance(node.op, ast.USub):
                return -left
        elif isinstance(node, ast.UnaryOp):
            operand = evaluate(node.operand)
            if isinstance(node.op, ast.Not):
                return not operand
        elif isinstance(node, ast.Compare):
            left = evaluate(node.left)
            ops = [ast.Lt, ast.LtE, ast.Gt, ast.GtE, ast.Eq, ast.NotEq]
            values = [evaluate(op.right) for op in node.ops]
            for op, value in zip(ops, values):
                if op == ast.Lt:
                    if left < value:
                        return True
                elif op == ast.LtE:
                    if left <= value:
                        return True
                elif op == ast.Gt:
                    if left > value:
                        return True
                elif op == ast.GtE:
                    if left >= value:
                        return True
                elif op == ast.Eq:
                    if left == value:
                        return True
                elif op == ast.NotEq:
                    if left != value:
                        return True
        elif isinstance(node, ast.BoolOp):
            values = [evaluate(child) for child in node.values]
            if node.op == ast.And:
                return all(values)
            elif node.op == ast.Or:
                return any(values)
        else:
            raise ValueError("Unsupported node type")

    # Evaluate the expression
    return evaluate(tree.body)

