import math

def evaluate_formula(formula: str, x: float) -> float:
    def parse_expression(tokens):
        if not tokens:
            return None
        token = tokens.pop(0)
        if token == '(':
            expr = parse_expression(tokens)
            if tokens.pop(0) != ')':
                raise ValueError("Unmatched parenthesis")
            return expr
        elif token in ('sqrt', 'abs', 'sin', 'cos'):
            if len(tokens) < 1:
                raise ValueError("Missing argument for function")
            arg = parse_expression(tokens)
            if arg is None:
                raise ValueError("Invalid expression")
            if token == 'sqrt':
                return math.sqrt(arg)
            elif token == 'abs':
                return abs(arg)
            elif token == 'sin':
                return math.sin(arg)
            elif token == 'cos':
                return math.cos(arg)
        elif token.isdigit() or '.' in token:
            try:
                return float(token)
            except ValueError:
                raise ValueError("Invalid number")
        elif token in ('+', '-', '*', '/', '**'):
            if len(tokens) < 2:
                raise ValueError("Missing operand")
            right = parse_expression(tokens)
            left = parse_expression(tokens)
            if left is None or right is None:
                raise ValueError("Invalid expression")
            if token == '+':
                return left + right
            elif token == '-':
                return left - right
            elif token == '*':
                return left * right
            elif token == '/':
                if right == 0:
                    raise ZeroDivisionError("Division by zero")
                return left / right
            elif token == '**':
                return left ** right
        else:
            raise ValueError(f"Unknown token: {token}")

    # Tokenize the formula
    tokens = []
    i = 0
    while i < len(formula):
        if formula[i].isspace():
            i += 1
            continue
        if formula[i] in ('+', '-', '*', '/', '**', '(', ')', 'sqrt', 'abs', 'sin', 'cos'):
            tokens.append(formula[i])
            i += 1
        elif formula[i].isdigit() or formula[i] == '.':
            j = i
            while j < len(formula) and (formula[j].isdigit() or formula[j] == '.'):
                j += 1
            tokens.append(formula[i:j])
            i = j
        else:
            raise ValueError(f"Invalid character: {formula[i]}")

    # Parse the expression
    return parse_expression(tokens)

