from collections import *

def teller_waits(arrivals: list[int], service_times: list[int], tellers: int) -> list[int]:
    if not arrivals or not service_times or tellers <= 0:
        return []

    n = len(arrivals)
    result = [0] * n
    teller_busy = [False] * tellers

    for i in range(n):
        # Find the next available teller
        for j in range(tellers):
            if not teller_busy[j]:
                teller_busy[j] = True
                result[i] = arrivals[i]
                break

        # Calculate the time the teller finishes serving the current customer
        finish_time = arrivals[i] + service_times[i]

        # Update the busy status of the teller
        for j in range(tellers):
            if teller_busy[j] and teller_busy[j] < finish_time:
                teller_busy[j] = finish_time

    return result

