import re

def is_allowed_webhook(url: str) -> bool:
    # Check if the URL starts with 'https://'
    if not url.startswith('https://'):
        return False

    # Remove 'https://' from the URL
    url = url[len('https://'):]

    # Check for backslashes, spaces, or control characters
    if any(char in url for char in r'\\ \t\n\r\f\v\x00-\x1F'):
        return False

    # Split the URL into scheme, netloc, and path
    parts = url.split('/', 1)
    scheme, netloc = parts

    # Check if the scheme is 'http' or 'https'
    if scheme not in ['http', 'https']:
        return False

    # Check if the netloc is empty
    if not netloc:
        return False

    # Check if the netloc ends with '.'
    if netloc.endswith('.'):
        netloc = netloc[:-1]

    # Check if the netloc contains '@' or ':' to separate user/password and port
    if '@' in netloc or ':' in netloc:
        user_info, host_port = netloc.split('@', 1)
        if ':' in host_port:
            host, port = host_port.split(':', 1)
        else:
            host, port = host_port, None
    else:
        user_info, host_port = '', netloc
        host, port = host_port, None

    # Check if the user_info contains invalid characters
    if user_info and not re.match(r'^[a-zA-Z0-9._%+-]+$', user_info):
        return False

    # Check if the host is a valid DNS name
    if not re.match(r'^[a-zA-Z0-9-]+\.[a-zA-Z0-9-.]+$', host):
        return False

    # Check if the host is 'localhost' or '.localhost'
    if host.lower() in ['localhost', '.localhost']:
        return False

    # Check if the port is None or 443
    if port and port != '443':
        return False

    # If all checks pass, return True
    return True

def format_table(rows: list[list[str]], aligns: str) -> str:
    if not rows:
        return ""

    # Calculate column widths
    col_widths = [max(len(cell) for cell in col) for col in zip(*rows)]

    # Create the table string
    table_str = ""
    for row in rows:
        formatted_row = []
        for i, cell in enumerate(row):
            width = col_widths[i]
            if aligns[i] == 'l':
                formatted_cell = cell.ljust(width)
            elif aligns[i] == 'r':
                formatted_cell = cell.rjust(width)
            else:  # aligns[i] == 'c'
                padding = (width - len(cell)) // 2
                formatted_cell = cell.center(width, ' ')
            formatted_row.append(formatted_cell)

        # Join cells with '| ' and add newline
        table_str += " | ".join(formatted_row) + "\n"

    return table_str.strip()

