import re

def tokenize_code(source: str) -> list[tuple[str, str]]:
    # Remove leading and trailing whitespace
    source = source.strip()

    if not source:
        return []

    tokens = []
    i = 0

    while i < len(source):
        if source[i].isspace():
            i += 1
            continue

        if source[i] in "+-*/<=>=":
            # Single character operator
            tokens.append(("OP", source[i]))
            i += 1
        elif source[i] == "(" or source[i] == ")":
            # Parentheses
            tokens.append(("OP", source[i]))
            i += 1
        elif source[i] == ",":
            # Comma
            tokens.append(("OP", source[i]))
            i += 1
        elif source[i] == ".":
            # Check for floating-point number
            if i + 1 < len(source) and source[i + 1].isdigit():
                j = i + 1
                while j < len(source) and source[j].isdigit():
                    j += 1
                if j - i > 1:
                    tokens.append(("NUMBER", source[i:j]))
                    i = j
                else:
                    raise ValueError("Invalid number format")
            else:
                raise ValueError("Invalid character after '.'")
        elif source[i].isalpha() or source[i] == "_":
            # Identifier
            j = i + 1
            while j < len(source) and (source[j].isalnum() or source[j] == "_"):
                j += 1
            tokens.append(("NAME", source[i:j]))
            i = j
        else:
            raise ValueError(f"Invalid character '{source[i]}' at position {i}")

    return tokens
