    # Remove the 'https://' prefix
    url = url[len('https://'):]

    # Check for invalid characters
    if re.search(r'[^\w.-]', url):
        return False

    # Split the URL into host and port
    parts = url.split(':')

    # Check if there's a port
    if len(parts) > 1:
        port = parts[1]
        # Check if the port is valid
        if not port.isdigit() or not (1 <= int(port) <= 65535):
            return False
    else:
        # Default to port 443 if no port is specified
        port = '443'

    # Split the host into labels
    labels = parts[0].split('.')

    # Check if the host is localhost
    if labels[0] == 'localhost':
        return False

    # Check if the host has more than one label
    if len(labels) < 2:
        return False

    # Check if the last label is empty
    if labels[-1] == '':
        return False

    # Check if all labels are valid
    for label in labels[:-1]:
        if not label.isalnum() or '-' in label:
            return False

    # Check if the last label is alphanumeric
    if not labels[-1].isalnum():
        return False

    return True

