def simulate_lru(capacity: int, operations: list[tuple]) -> tuple[list, list]:
    cache = OrderedDict()
    results = []
    keys = []

    for op, key, value in operations:
        if op == "put":
            if key in cache:
                del cache[key]
            cache[key] = value
            if len(cache) > capacity:
                cache.popitem(last=False)
        elif op == "get":
            if key in cache:
                results.append(cache[key])
                cache.move_to_end(key)
                keys = list(cache.keys())
            else:
                results.append(None)

    return results, keys
