        if node == goal:
            if cost < min_cost or (cost == min_cost and path < best_path):
                min_cost = cost
                best_path = path[:]
            return

        for neighbor, weight in graph[node]:
            if neighbor not in path:
                path.append(neighbor)
                dfs(neighbor, cost + weight, path)
                path.pop()

