def evaluate_expression(expr: str) -> int:
    def parse_expr(tokens):
        if not tokens:
            return 0

        token = tokens.pop(0)

        if token.isdigit():
            return int(token)

        if token == '(':
            result = parse_expr(tokens)
            if tokens and tokens[0] == ')':
                tokens.pop(0)
            return result

        if token in ['+', '-', '*', '/', '^']:
            precedence = {'+': 1, '-': 1, '*': 2, '/': 2, '^': 3}
            right_associative = {'^'}

            right = parse_expr(tokens)
            while tokens and precedence.get(tokens[-1], 0) >= precedence[token] and (token not in right_associative or tokens[-2] == '('):
                op = tokens.pop()
                if op == '+':
                    right += parse_expr(tokens)
                elif op == '-':
                    right -= parse_expr(tokens)
                elif op == '*':
                    right *= parse_expr(tokens)
                elif op == '/':
                    divisor = parse_expr(tokens)
                    if divisor == 0:
                        raise ZeroDivisionError("Division by zero")
                    right //= divisor
                elif op == '^':
                    right **= parse_expr(tokens)

            return right

        raise ValueError(f"Invalid token: {token}")

    # Remove spaces from the expression
    expr = expr.replace(' ', '')

    # Tokenize the expression
    tokens = re.findall(r'\d+|\+|\-|\*|\/|\^|\(|\)', expr)

    return parse_expr(tokens)

