    pattern = r'^\s*(?:(?:[a-zA-Z_][a-zA-Z0-9_]*)\s*([<>=!]=?)\s*[-+]?(\d+(\.\d+)?)|true|false)\s*(?:and|or|not)\s*(?:(?:[a-zA-Z_][a-zA-Z0-9_]*)\s*([<>=!]=?)\s*[-+]?(\d+(\.\d+)?)|true|false))?$'

