import re

def is_allowed_webhook(url: str) -> bool:
    # Check if the URL starts with 'https://'
    if not url.startswith('https://'):
        return False

    # Remove any leading or trailing whitespace
    url = url.strip()

    # Check for backslashes, spaces, or control characters
    if re.search(r'[\\ / \t\r\n\f\v]', url):
        return False

    # Split the URL into scheme, netloc, and path
    parts = url.split('//')
    if len(parts) != 2:
        return False

    netloc = parts[1]

    # Check if the netloc contains a '@' symbol
    if '@' in netloc:
        user_info, netloc = netloc.split('@', 1)
        # Check if the user info contains a ':' symbol
        if ':' in user_info:
            username, password = user_info.split(':', 1)
            # Check if the username and password are valid
            if not (username.isalnum() and password.isalnum()):
                return False
        else:
            # Check if the username is valid
            if not username.isalnum():
                return False

    # Check if the netloc ends with a '.'
    if netloc.endswith('.'):
        netloc = netloc[:-1]

    # Check if the netloc is a valid domain name
    if not re.match(r'^[a-zA-Z0-9-]+\.[a-zA-Z0-9-.]+$', netloc):
        return False

    # Check if the netloc is not localhost or .localhost
    if netloc.lower() in ['localhost', '.localhost']:
        return False

    # Check if the netloc contains a port
    if ':' in netloc:
        _, port = netloc.split(':', 1)
        # Check if the port is 443
        if port != '443':
            return False

    # If all checks pass, the URL is allowed
    return True

