def parse_csv(text: str) -> list[list[str]]:
    def parse_field(field: str) -> str:
        if field.startswith('"'):
            # Handle quoted fields
            result = []
            i = 1
            while i < len(field):
                if field[i] == '"':
                    # Check for escaped double quotes
                    if i + 1 < len(field) and field[i + 1] == '"':
                        result.append('"')
                        i += 2
                    else:
                        break
                elif field[i] == ',' or field[i] == '\n':
                    break
                else:
                    result.append(field[i])
                i += 1
            return ''.join(result)
        else:
