import ipaddress

def is_public_ip(ip_str: str) -> bool:
    try:
        # Try to parse the IP address
        ip = ipaddress.ip_address(ip_str)

        # Check if the IP is public
        if ip.is_global:
            return True

        # Check if the IP is in a private range
        if ip.is_private:
            return False

        # Check if the IP is a loopback address
        if ip.is_loopback:
            return False

        # Check if the IP is a link-local address
        if ip.is_link_local:
            return False

        # Check if the IP is a multicast address
        if ip.is_multicast:
            return False

        # Check if the IP is unspecified
        if ip.is_unspecified:
            return False

        # Check if the IP is reserved
        if ip.is_reserved:
            return False

        # Check if the IP is documentation
        if ip.is_documentation:
            return False

        # Check if the IP is in the shared space 100.64.0.0/10
        if ip.version == 4 and ip in ipaddress.ip_network('100.64.0.0/10'):
            return False

        # Check if the IP is a broadcast address
        if ip.version == 4 and ip.is_broadcast:
            return False

        # If none of the above conditions are met, it's a public IP
        return True

    except ValueError:
        # If parsing fails, the IP is not in standard form
        return False
