import re

def evaluate_expression(expr: str) -> int:
    def apply_operator(operators, values):
        operator = operators.pop()
        right = values.pop()
        left = values.pop()
        if operator == '+':
            values.append(left + right)
        elif operator == '-':
            values.append(left - right)
        elif operator == '*':
            values.append(left * right)
        elif operator == '/':
            if right == 0:
                raise ZeroDivisionError("Division by zero")
            values.append(left // right)
        elif operator == '^':
            values.append(left ** right)

    def apply_unary_minus(values):
        value = values.pop()
        values.append(-value)

    def parse_expression(expr: str) -> list:
        tokens = re.findall(r'\d+|\+|-|\*|\/|\^|\(|\)', expr)
        values = []
        operators = []
        i = 0
        while i < len(tokens):
            token = tokens[i]
            if token.isdigit():
                values.append(int(token))
            elif token in '+-*/^':
                while (operators and operators[-1] in '*/^' and
                       precedence(operators[-1]) >= precedence(token)):
                    apply_operator(operators, values)
                operators.append(token)
            elif token == '(':
                operators.append(token)
            elif token == ')':
                while operators[-1] != '(':
                    apply_operator(operators, values)
                operators.pop()  # Remove '('
            i += 1
        while operators:
            apply_operator(operators, values)
        return values

    def precedence(op):
        if op in '*/^':
            return 2
        elif op in '+-':
            return 1
        return 0

    try:
        values = parse_expression(expr)
        if len(values) != 1:
            raise ValueError("Invalid expression")
        return values[0]
    except ZeroDivisionError as e:
        raise e
    except Exception as e:
        raise ValueError(f"Error evaluating expression: {e}")

# Example usage:
print(evaluate_expression("2^3^2"))  # Output: 512
print(evaluate_expression("-2^2"))  # Output: -4
print(evaluate_expression("7/-2"))   # Output: -3
```

