    # Remove spaces from the expression
    expr = expr.replace(" ", "")

    # Define a helper function to evaluate a sub-expression
    def eval_sub_expr(expr: str) -> int:
        stack = []
        current_num = ""

        for char in expr:
            if char.isdigit():
                current_num += char
            elif char == '(':
                stack.append(current_num)
                current_num = ""
                stack.append(char)
            elif char == ')':
                while stack and stack[-1] != '(':
                    num = stack.pop()
                    if stack and stack[-1] == '^':
                        stack.pop()
                        num2 = stack.pop()
                        stack.append(int(num2 ** int(num)))
                    else:
                        stack.append(int(num))
                stack.pop()  # Pop the '('
                if stack and stack[-1] == '-':
                    stack.pop()
                    num = stack.pop()
                    stack.append(-int(num))
                else:
                    stack.append(int(current_num))
            elif char in '+-*/^':
                while stack and stack[-1] in '+-*/^' and precedence(stack[-1]) >= precedence(char):
                    num = stack.pop()
                    if stack and stack[-1] == '^':
                        stack.pop()
                        num2 = stack.pop()
                        stack.append(int(num2 ** int(num)))
                    else:
