    stack = []
    index = 0
    max_instructions = 1000

    while index < len(program):
        if index >= max_instructions:
            raise RuntimeError("Program too long")

        instruction = program[index]
        parts = instruction.split()

        if parts[0] == "PUSH":
            try:
                value = int(parts[1])
                stack.append(value)
            except ValueError:
                raise ValueError(f"Invalid number: {parts[1]}")
        elif parts[0] == "POP":
            if not stack:
                raise ValueError("Stack is empty")
            stack.pop()
        elif parts[0] == "DUP":
            if not stack:
                raise ValueError("Stack is empty")
            stack.append(stack[-1])
        elif parts[0] == "SWAP":
            if len(stack) < 2:
                raise ValueError("Not enough elements in stack")
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif parts[0] == "ADD":
            if len(stack) < 2:
                raise ValueError("Not enough elements in stack")
            a = stack.pop()
            b = stack.pop()
            stack.append(a + b)
        elif parts[0] == "SUB":
            if len(stack) < 2:
                raise ValueError("Not enough elements in stack")
            a = stack.pop()
            b = stack.pop()
            stack.append(b - a)
        elif parts[0] == "MUL":
            if len(stack) < 2:
                raise ValueError("Not enough elements in stack")
            a = stack.pop()
            b = stack.pop()
            stack.append(a * b)
        elif parts[0] == "JMP":
            try:
                target = int(parts[1])
                index = target - 1  # Adjust for 0-based indexing
            except ValueError:
                raise ValueError(f"Invalid jump target: {parts[1]}")
        elif parts[0] == "JZ":
            if len(stack) < 1:
                raise ValueError("Not enough elements in stack")
            value = stack.pop()
            if value == 0:
                try:
                    target = int(parts[1])
                    index = target - 1  # Adjust for 0-based indexing
                except ValueError:
                    raise ValueError(f"Invalid jump target: {parts[1]}")
        elif parts[0] == "HALT":
            break
        else:
            raise ValueError(f"Unknown instruction: {instruction}")

        index += 1

    return stack
