def evaluate_expression(expr: str) -> int:
    # Remove spaces from the expression
    expr = expr.replace(" ", "")

    # Define a regular expression to match the expression
    pattern = r"(-?\d+)(\^(-?\d+))?(?:(?:\*|\/|-|\+)(-?\d+))?"

    def parse_term(match):
        num = int(match.group(1))
        if match.group(2):
            exponent = int(match.group(3))
            return num ** exponent
        elif match.group(4):
            op = match.group(4)
            next_num = int(match.group(5))
            if op == '*':
                return num * next_num
            elif op == '/':
                if next_num == 0:
                    raise ZeroDivisionError("Division by zero")
