def run_stack_program(program: list[str]) -> list[int] | None:
    stack = []
    index = 0
    max_instructions = 1000

    while index < len(program) and index < max_instructions:
        instruction = program[index]

        if instruction.startswith('PUSH'):
            try:
                value = int(instruction.split()[1])
                stack.append(value)
            except ValueError:
                return None

        elif instruction == 'POP':
            if not stack:
                return None
            stack.pop()

        elif instruction == 'DUP':
            if not stack:
                return None
            stack.append(stack[-1])

        elif instruction == 'SWAP':
            if len(stack) < 2:
                return None
            stack[-1], stack[-2] = stack[-2], stack[-1]

        elif instruction.startswith('ADD'):
            if len(stack) < 2:
                return None
            a, b = stack.pop(), stack.pop()
            stack.append(a + b)

        elif instruction.startswith('SUB'):
            if len(stack) < 2:
                return None
            a, b = stack.pop(), stack.pop()
            stack.append(a - b)

        elif instruction.startswith('MUL'):
            if len(stack) < 2:
                return None
            a, b = stack.pop(), stack.pop()
            stack.append(a * b)

        elif instruction.startswith('JMP'):
            try:
                target = int(instruction.split()[1])
                if target < 0 or target >= len(program):
                    return None
                index = target
            except ValueError:
                return None

        elif instruction.startswith('JZ'):
            try:
                target = int(instruction.split()[1])
                if target < 0 or target >= len(program):
                    return None
                if not stack:
                    index = target
                else:
                    stack.pop()
            except ValueError:
                return None

        else:
            return None

        index += 1

    if index == len(program):
        return stack
    else:
        return None
