import ipaddress

def is_public_ip(ip_str: str) -> bool:
    try:
        # Try to parse the IP address using ipaddress module
        ip = ipaddress.ip_address(ip_str)

        # Check if the IP is in a private range
        if ip.is_private or ip.is_loopback or ip.is_link_local or ip.is_multicast or ip.is_unspecified or ip.is_reserved or ip.is_documentation:
            return False

        # Check if the IP is in the shared space 100.64.0.0/10
        if ip.version == 4 and ip >= ipaddress.IPv4Address('100.64.0.0') and ip < ipaddress.IPv4Address('100.65.0.0'):
            return False

        # Check if the IP is the broadcast address of IPv4
        if ip.version == 4 and ip == ipaddress.IPv4Address('255.255.255.255'):
            return False

        # If all checks pass, the IP is public
        return True

    except ValueError:
        # If parsing fails, the IP is not in standard format
        return False

