        self.stack = []
        self.ip = 0

    def execute(self, program: list[str]) -> list[int]:
        max_instructions = 1000
        while self.ip < len(program) and self.ip <= max_instructions:
            instruction = program[self.ip]
            parts = instruction.split()
            if parts[0] == 'PUSH':
                if len(parts) != 2:
                    raise ValueError("Invalid PUSH instruction")
                try:
                    value = int(parts[1])
                    self.stack.append(value)
                except ValueError:
                    raise ValueError("Invalid integer value for PUSH")
            elif parts[0] == 'POP':
                if len(parts) != 1:
                    raise ValueError("Invalid POP instruction")
                if not self.stack:
                    raise ValueError("Stack is empty for POP")
                self.stack.pop()
            elif parts[0] == 'DUP':
                if len(parts) != 1:
                    raise ValueError("Invalid DUP instruction")
                if not self.stack:
                    raise ValueError("Stack is empty for DUP")
                self.stack.append(self.stack[-1])
            elif parts[0] == 'SWAP':
                if len(parts) != 1:
                    raise ValueError("Invalid SWAP instruction")
                if len(self.stack) < 2:
                    raise ValueError("Stack has less than two elements for SWAP")
                self.stack[-1], self.stack[-2] = self.stack[-2], self.stack[-1]
            elif parts[0] in ['ADD', 'SUB', 'MUL']:
                if len(parts) != 2:
                    raise ValueError(f"Invalid {parts[0]} instruction")
                if len(self.stack) < 2:
                    raise ValueError(f"Stack has less than two elements for {parts[0]}")
                a = self.stack.pop()
                b = self.stack.pop()
                if parts[0] == 'ADD':
                    result = a + b
                elif parts[0] == 'SUB':
                    result = a - b
                elif parts[0] == 'MUL':
                    result = a * b
                self.stack.append(result)
            elif parts[0] == 'JMP':
                if len(parts) != 2:
                    raise ValueError("Invalid JMP instruction")
