    def __init__(self):
        self.stack = []
        self.ip = 0

    def run(self, program: list[str]) -> list[int]:
        max_instructions = 1000
        while self.ip < len(program) and self.ip <= max_instructions:
            instruction = program[self.ip]
            parts = instruction.split()
            if parts[0] == 'PUSH':
                if len(parts) != 2:
                    raise ValueError("Invalid PUSH instruction")
                try:
                    value = int(parts[1])
                except ValueError:
                    raise ValueError("Invalid integer in PUSH instruction")
                self.stack.append(value)
            elif parts[0] == 'POP':
                if len(parts) != 1:
                    raise ValueError("Invalid POP instruction")
                if not self.stack:
                    raise ValueError("Stack is empty for POP operation")
                self.stack.pop()
            elif parts[0] == 'DUP':
                if len(parts) != 1:
                    raise ValueError("Invalid DUP instruction")
                if not self.stack:
                    raise ValueError("Stack is empty for DUP operation")
                self.stack.append(self.stack[-1])
            elif parts[0] == 'SWAP':
                if len(parts) != 1:
                    raise ValueError("Invalid SWAP instruction")
                if len(self.stack) < 2:
                    raise ValueError("Stack has less than two elements for SWAP operation")
                self.stack[-1], self.stack[-2] = self.stack[-2], self.stack[-1]
            elif parts[0] == 'ADD':
                if len(parts) != 1:
                    raise ValueError("Invalid ADD instruction")
                if len(self.stack) < 2:
                    raise ValueError("Stack has less than two elements for ADD operation")
                a = self.stack.pop()
                b = self.stack.pop()
                self.stack.append(a + b)
            elif parts[0] == 'SUB':
                if len(parts) != 1:
                    raise ValueError("Invalid SUB instruction")
                if len(self.stack) < 2:
                    raise ValueError("Stack has less than two elements for SUB operation")
                a = self.stack.pop()
                b = self.stack.pop()
                self.stack.append(b - a)
            elif parts[0] == 'MUL':
                if len(parts) != 1:
                    raise ValueError("Invalid MUL instruction")
                if len(self.stack) < 2:
                    raise ValueError("Stack has less than two elements for MUL operation")
                a = self.stack.pop()
                b = self.stack.pop()
                self.stack.append(a * b)
            elif parts[0] == 'JMP':
                if len(parts) != 2:
                    raise ValueError("Invalid JMP instruction")
                try:
                    target = int(parts[1])
                except ValueError:
                    raise ValueError("Invalid integer in JMP instruction")
                self.ip = target
            elif parts[0] == 'JZ':
                if len(parts) != 2:
                    raise ValueError("Invalid JZ instruction")
                try:
                    target = int(parts[1])
                except ValueError:
                    raise ValueError("Invalid integer in JZ instruction")
                if not self.stack:
                    raise ValueError("Stack is empty for JZ operation")
                if self.stack[-1] == 0:
                    self.ip = target
                else:
                    self.ip += 1
            elif parts[0] == 'HALT':
                break
            else:
                raise ValueError(f"Unknown instruction: {instruction}")
            self.ip += 1
        if self.ip > max_instructions:
            raise RuntimeError("Maximum number of instructions executed")
        return self.stack[::-1]

