def run_stack_program(program: list[str]) -> list[int] | None:
    stack = []
    ip = 0
    max_instructions = 1000

    while ip < len(program) and max_instructions > 0:
        instruction = program[ip]
        parts = instruction.split()

        if parts[0] == "PUSH":
            try:
                stack.append(int(parts[1]))
            except ValueError:
                return None
        elif parts[0] == "POP":
            if not stack:
                return None
            stack.pop()
        elif parts[0] == "DUP":
            if not stack:
                return None
            stack.append(stack[-1])
        elif parts[0] == "SWAP":
            if len(stack) < 2:
                return None
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif parts[0] == "ADD":
            if len(stack) < 2:
                return None
            b = stack.pop()
            a = stack.pop()
            stack.append(a + b)
        elif parts[0] == "SUB":
            if len(stack) < 2:
                return None
            b = stack.pop()
            a = stack.pop()
            stack.append(a - b)
        elif parts[0] == "MUL":
            if len(stack) < 2:
                return None
            b = stack.pop()
            a = stack.pop()
            stack.append(a * b)
        elif parts[0] == "JMP":
            try:
                target = int(parts[1])
                if target < 0 or target >= len(program):
                    return None
                ip = target
            except ValueError:
                return None
        elif parts[0] == "JZ":
            if len(stack) < 1:
                return None
            b = stack.pop()
            if b == 0:
                try:
                    target = int(parts[1])
                    if target < 0 or target >= len(program):
                        return None
                    ip = target
                except ValueError:
                    return None
        else:
            return None

        ip += 1
        max_instructions -= 1

    return stack if ip == len(program) else None
