from collections import defaultdict

def process_orders(events: list[tuple[str, str, int]]) -> tuple[dict[str, int], list[tuple[str, int]]]:
    stock = defaultdict(int)
    waiting = []

    for kind, item, quantity in events:
        if kind == 'receive':
            stock[item] += quantity
        elif kind == 'order':
            if stock[item] >= quantity:
                stock[item] -= quantity
                waiting.append((item, quantity))
            else:
                waiting.append((item, quantity))

    # Ship orders that can be shipped
    while waiting:
        item, quantity = waiting.pop(0)
        if stock[item] >= quantity:
            stock[item] -= quantity
        else:
            waiting.append((item, quantity - stock[item]))
            stock[item] = 0

    return dict(stock), waiting
