from typing import List, Optional

def run_stack_program(program: List[str]) -> List[int] | None:
    stack = []
    ip = 0
    max_instructions = 1000

    while ip < len(program):
        if ip >= max_instructions:
            return None  # Endless loop detected

        instruction = program[ip]
        parts = instruction.split()

        if parts[0] == "PUSH":
            try:
                value = int(parts[1])
                stack.append(value)
            except ValueError:
                return None  # Invalid number format

        elif parts[0] == "POP":
            if not stack:
                return None  # Stack underflow
            stack.pop()

        elif parts[0] == "DUP":
            if not stack:
                return None  # Stack underflow
            stack.append(stack[-1])

        elif parts[0] == "SWAP":
            if len(stack) < 2:
                return None  # Not enough elements in stack
            stack[-1], stack[-2] = stack[-2], stack[-1]

        elif parts[0] == "ADD":
            if len(stack) < 2:
                return None  # Not enough elements in stack
            b = stack.pop()
            a = stack.pop()
            stack.append(a + b)

        elif parts[0] == "SUB":
            if len(stack) < 2:
                return None  # Not enough elements in stack
            b = stack.pop()
            a = stack.pop()
            stack.append(a - b)

        elif parts[0] == "MUL":
            if len(stack) < 2:
                return None  # Not enough elements in stack
            b = stack.pop()
            a = stack.pop()
            stack.append(a * b)

        elif parts[0] == "JMP":
            try:
                target = int(parts[1])
                if target < 0 or target >= len(program):
                    return None  # Invalid jump target
                ip = target
            except ValueError:
                return None  # Invalid jump target format

        elif parts[0] == "JZ":
            if len(stack) < 1:
                return None  # Not enough elements in stack
            value = stack.pop()
            if value == 0:
                try:
                    target = int(parts[1])
                    if target < 0 or target >= len(program):
                        return None  # Invalid jump target
                    ip = target
                except ValueError:
                    return None  # Invalid jump target format

        else:
            return None  # Unknown instruction

        ip += 1

    return stack
