from collections import *

def run_bank_ops(balances: dict[str, int], ops: list[tuple]) -> tuple[dict[str, int], list[int]]:
    final_balances = balances.copy()
    failed = []

    for op in ops:
        if len(op) != 3:
            failed.append(0)
            continue

        action, account, amount = op

        if account not in balances:
            failed.append(1)
            continue

        if action == 'deposit':
            if amount <= 0:
                failed.append(2)
                continue
            final_balances[account] += amount
        elif action == 'withdraw':
            if amount <= 0:
                failed.append(3)
                continue
            if final_balances[account] < amount:
                failed.append(4)
                continue
            final_balances[account] -= amount
        elif action == 'transfer':
            if amount <= 0 or amount > final_balances[account]:
                failed.append(5)
                continue
            if account == target:
                failed.append(6)
                continue
            final_balances[account] -= amount
            final_balances[target] += amount - 2
        elif action == 'freeze':
            if account not in final_balances:
                failed.append(7)
                continue
            final_balances[account] = 0
        elif action == 'unfreeze':
            if account not in final_balances:
                failed.append(8)
                continue
            if final_balances[account] == 0:
                final_balances[account] = balances[account]
        else:
            failed.append(9)

    return final_balances, failed
