def run_stack_machine(program: list[str]) -> list[int]:
    stack = []
    pc = 0  # Program Counter
    max_instructions = 1000

    while pc < len(program):
        instruction = program[pc]
        parts = instruction.split()

        if len(parts) == 0:
            raise ValueError("Invalid instruction")

        opcode = parts[0]

        if opcode == "PUSH":
            try:
                value = int(parts[1])
                stack.append(value)
            except ValueError:
                raise ValueError(f"Invalid number for PUSH: {parts[1]}")
        elif opcode == "POP":
            if len(stack) == 0:
                raise ValueError("POP from empty stack")
            stack.pop()
        elif opcode == "DUP":
            if len(stack) == 0:
                raise ValueError("DUP from empty stack")
            stack.append(stack[-1])
        elif opcode == "SWAP":
            if len(stack) < 2:
                raise ValueError("SWAP requires at least two elements on the stack")
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif opcode == "ADD":
            if len(stack) < 2:
                raise ValueError("ADD requires at least two elements on the stack")
            a = stack.pop()
            b = stack.pop()
            stack.append(a + b)
        elif opcode == "SUB":
            if len(stack) < 2:
                raise ValueError("SUB requires at least two elements on the stack")
            a = stack.pop()
            b = stack.pop()
            stack.append(a - b)
        elif opcode == "MUL":
            if len(stack) < 2:
                raise ValueError("MUL requires at least two elements on the stack")
            a = stack.pop()
            b = stack.pop()
            stack.append(a * b)
        elif opcode == "JMP":
            try:
                target = int(parts[1])
                if target < 0 or target >= len(program):
                    raise ValueError(f"JMP target out of range: {target}")
                pc = target
            except ValueError:
                raise ValueError(f"Invalid target for JMP: {parts[1]}")
        elif opcode == "JZ":
            if len(stack) == 0:
                raise ValueError("JZ from empty stack")
            value = stack.pop()
            if value == 0:
                try:
                    target = int(parts[1])
                    if target < 0 or target >= len(program):
                        raise ValueError(f"JZ target out of range: {target}")
                    pc = target
                except ValueError:
                    raise ValueError(f"Invalid target for JZ: {parts[1]}")
            else:
                pc += 1
        elif opcode == "HALT":
            break
        else:
            raise ValueError(f"Unknown opcode: {opcode}")

        pc += 1

        if pc >= max_instructions:
            raise RuntimeError("Maximum instructions reached")

    return stack
