    stack = []
    pc = 0
    max_instructions = 1000

    while pc < len(program) and max_instructions > 0:
        instruction = program[pc]
        parts = instruction.split()

        if parts[0] == "PUSH":
            try:
                value = int(parts[1])
                stack.append(value)
            except ValueError:
                return None
        elif parts[0] == "POP":
            if not stack:
                return None
            stack.pop()
        elif parts[0] == "DUP":
            if not stack:
                return None
            stack.append(stack[-1])
