            if len(stack) < 2:
                return None
            b = stack.pop()
            a = stack.pop()
            stack.append(a - b)
        elif parts[0] == "MUL":
            if len(stack) < 2:
                return None
            b = stack.pop()
            a = stack.pop()
            stack.append(a * b)
