from typing import *
from collections import *

def run_bank_ops(balances: dict[str, int], ops: list[tuple]) -> tuple[dict[str, int], list[int]]:
    final_balances = balances.copy()
    failed = []

    for i, (op, *args) in enumerate(ops):
        if op == 'deposit':
            if args[1] not in final_balances:
                failed.append(i)
                continue
            if args[2] <= 0:
                failed.append(i)
                continue
            final_balances[args[1]] += args[2]
        elif op == 'withdraw':
            if args[1] not in final_balances:
                failed.append(i)
                continue
            if args[2] <= 0:
                failed.append(i)
                continue
            if final_balances[args[1]] < args[2]:
                failed.append(i)
                continue
            final_balances[args[1]] -= args[2]
        elif op == 'transfer':
            if args[1] not in final_balances or args[2] not in final_balances:
                failed.append(i)
                continue
            if args[1] == args[2]:
                failed.append(i)
                continue
            if final_balances[args[1]] < args[2] + 2:
                failed.append(i)
                continue
            final_balances[args[1]] -= args[2] + 2
            final_balances[args[2]] += args[2]
        elif op == 'freeze':
            if args[1] not in final_balances:
                failed.append(i)
                continue
            final_balances[args[1]] |= 1 << 31
        elif op == 'unfreeze':
            if args[1] not in final_balances:
                failed.append(i)
                continue
            final_balances[args[1]] &= ~(1 << 31)
        else:
            failed.append(i)

    return final_balances, failed
