from collections import Counter

def is_subset_list(a: list, b: list) -> bool:
    # If list a is empty, it is trivially a subset of any list
    if not a:
        return True

    # Count occurrences of each element in both lists
    count_a = Counter(a)
    count_b = Counter(b)

    # Check if all elements in a are present in b with at least the same frequency
    for element, freq in count_a.items():
        if count_b[element] < freq:
            return False

    return True

