def count_set_bits_range(lo: int, hi: int) -> int:
    if lo > hi:
        return 0

    def count_set_bits(n: int) -> int:
        if n == 0:
            return 0
        # Find the highest power of 2 less than or equal to n
        highest_power_of_2 = 1 << (n.bit_length() - 1)
        return n - (highest_power_of_2 - 1)

    total_count = 0
    for i in range(lo, hi + 1):
        total_count += count_set_bits(i)

    return total_count

