def count_set_bits_range(lo: int, hi: int) -> int:
    if lo > hi:
        return 0

    # Helper function to count set bits in a single number
    def count_set_bits(n: int) -> int:
        count = 0
        while n:
            count += n & 1
            n >>= 1
        return count

    # Calculate the total number of set bits in the range [0, hi]
    total_set_bits = sum(count_set_bits(i) for i in range(hi + 1))

    # Calculate the total number of set bits in the range [0, lo - 1]
    if lo > 0:
        total_set_bits -= sum(count_set_bits(i) for i in range(lo))

    return total_set_bits

