def pack_bins(sizes: list[int], capacity: int) -> list[list[int]]:
    if not sizes:
        return []

    bins = []
    sizes.sort(reverse=True)

    for size in sizes:
        if size > capacity:
            raise ValueError("Item size exceeds capacity")

        found_bin = False
        for bin in bins:
            if sum(bin) + size <= capacity:
                bin.append(size)
                found_bin = True
                break

        if not found_bin:
            bins.append([size])

    return bins
