def rotate_rings(matrix: list[list[int]], k: int) -> list[list[int]]:
    if not matrix or not matrix[0]:
        return []

    n = len(matrix)
    result = [[0] * n for _ in range(n)]

    for i in range(n):
        for j in range(n):
            # Calculate the distance from the center
            dist = min(i, j, n - 1 - i, n - 1 - j)

            # Calculate the new position after rotation
            new_i = i + (j - dist) * (-1 if k > 0 else 1)
            new_j = j + (i - dist) * (-1 if k > 0 else 1)

            # Ensure the new position is within bounds
            if 0 <= new_i < n and 0 <= new_j < n:
                result[new_i][new_j] = matrix[i][j]

    return result

from typing import List

def weighted_harmonic_mean(vals: List[float], weights: List[float]) -> float:
    if not vals or len(vals) != len(weights) or sum(weights) == 0:
        return 0.0

    numerator = sum(1 / (val * weight) for val, weight in zip(vals, weights))
    denominator = sum(weight for weight in weights)

    return round(numerator / denominator, 3)

