    if not matrix or k == 0:
        return matrix

    n = len(matrix)
    if k >= n // 2:
        return matrix

    def rotate_ring(start_row, start_col, end_row, end_col):
        nonlocal matrix
        if k == 0:
            return

        # Rotate the top row
        for j in range(start_col + 1, end_col):
            matrix[start_row][j], matrix[start_row][j + 1] = matrix[start_row][j + 1], matrix[start_row][j]

        # Rotate the right column
        for i in range(start_row + 1, end_row):
            matrix[i][end_col], matrix[i + 1][end_col] = matrix[i + 1][end_col], matrix[i][end_col]

        # Rotate the bottom row
