def shortest_path_one_break(grid: list[str]) -> int:
    if not grid or 'S' not in grid or 'E' not in grid:
        return -1

    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    queue = deque([(0, 0, 0)])  # (row, col, breaks)
    visited = set()

    while queue:
        row, col, breaks = queue.popleft()

        if (row, col) == (rows - 1, cols - 1):
            return breaks

        if (row, col, breaks) in visited:
            continue
        visited.add((row, col, breaks))

        for dr, dc in directions:
