from math import gcd
from functools import reduce

def lcm(a, b):
    return abs(a*b) // gcd(a, b)

def solve_congruences(congruences: list[tuple[int, int]]) -> tuple[int, int] | None:
    if not congruences:
        return (0, 1)

    L = reduce(lcm, [m for _, m in congruences])
    x = 0

    for r, m in congruences:
        # Normalize r to be within the range [0, m-1]
        r %= m
        # Find the inverse of m modulo L
        inv_m = pow(m, -1, L)
        # Update x using the Chinese Remainder Theorem formula
        x += r * inv_m * L // m

    # Ensure x is within the range [0, L-1]
    x %= L

    return (x, L)
```

