from collections import deque

def shortest_path_one_break(grid: list[str]) -> int:
    if not grid or 'S' not in grid or 'E' not in grid:
        return -1

    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    start, end = None, None

    # Find the starting and ending points
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    if start is None or end is None:
        return -1

    queue = deque([(start, 0, False)])  # (current position, moves, has_passed_wall)
    visited = set()

    while queue:
        current, moves, has_passed_wall = queue.popleft()

        if current == end:
            return moves

        for dx, dy in directions:
            nx, ny = current[0] + dx, current[1] + dy

            if 0 <= nx < rows and 0 <= ny < cols:
                if grid[nx][ny] == '#':
                    if not has_passed_wall:
                        queue.append(((nx, ny), moves + 1, True))
                else:
                    if (nx, ny, has_passed_wall) not in visited:
                        visited.add((nx, ny, has_passed_wall))
                        queue.append(((nx, ny), moves + 1, has_passed_wall))

    return -1
