import re

def evaluate_expression(expression: str) -> float:
    def apply_operator(operators, values):
        operator = operators.pop()
        right = values.pop()
        left = values.pop()
        if operator == '+':
            values.append(left + right)
        elif operator == '-':
            values.append(left - right)
        elif operator == '*':
            values.append(left * right)
        elif operator == '/':
            if right == 0:
                raise ZeroDivisionError("Division by zero")
            values.append(left / right)
        elif operator == '**':
            values.append(left ** right)

    def greater_precedence(op1, op2):
        precedence = {'+': 1, '-': 1, '*': 2, '/': 2, '**': 3}
        return precedence[op1] > precedence[op2]

    def apply_parentheses(expression):
        stack = []
        i = 0
        while i < len(expression):
            if expression[i] == '(':
                stack.append(i)
            elif expression[i] == ')':
                start = stack.pop()
                sub_expr = expression[start + 1:i]
                try:
                    value = evaluate_expression(sub_expr)
                    expression = expression[:start] + str(value) + expression[i + 1:]
                except Exception as e:
                    raise ValueError(f"Invalid expression: {e}")
            i += 1
        return expression

    # Remove spaces from the expression
    expression = expression.replace(' ', '')

    # Check for invalid characters
    if not re.match(r'^[\d+\-*/().]+$', expression):
        raise ValueError("Invalid expression")

    # Apply parentheses first
    expression = apply_parentheses(expression)

    # Initialize stacks for operators and values
    operators = []
    values = []

    # Tokenize the expression
    tokens = re.findall(r'\d+\.\d+|\d+|[+\-*/()]', expression)

    for token in tokens:
        if token.isdigit():
            values.append(float(token))
        elif token in '+-*/':
            while (operators and operators[-1] != '(' and
