                apply_operator(operators, values)
            if operators and operators[-1] == '(':
                operators.pop()

    # Apply remaining operators
    while operators:
        apply_operator(operators, values)

    # The final result should be the only value left in the stack
    if len(values) != 1:
        raise ValueError("Invalid expression")
    return values[0]
