import re

def evaluate_expression(expression: str) -> float:
    # Regular expression to match valid tokens in the expression
    token_pattern = r'\d+\.\d+|\d+|\+|-|\*|/|\^|\(|\)'

    # Tokenize the expression
    tokens = re.findall(token_pattern, expression)

    # Function to apply an operator to two operands
    def apply_operator(operators, values):
        operator = operators.pop()
        right = values.pop()
        left = values.pop()
        if operator == '+':
            values.append(left + right)
        elif operator == '-':
            values.append(left - right)
        elif operator == '*':
            values.append(left * right)
        elif operator == '/':
            if right == 0:
                raise ZeroDivisionError("Division by zero")
            values.append(left / right)
        elif operator == '^':
            values.append(left ** right)

    # Evaluate the expression using a stack-based approach
    operators = []
    values = []
    i = 0
    while i < len(tokens):
        token = tokens[i]
        if token.isdigit() or '.' in token:
            # Parse number
            value = float(token)
            values.append(value)
        elif token in ('+', '-', '*', '/', '^'):
            # Handle operators
            while (operators and operators[-1] in ('*', '/', '^') and
                   precedence(operators[-1]) >= precedence(token)):
                apply_operator(operators, values)
            operators.append(token)
        elif token == '(':
            # Push opening parenthesis onto stack
            operators.append(token)
        elif token == ')':
            # Pop operators from stack until matching '('
            while operators and operators[-1] != '(':
                apply_operator(operators, values)
            if operators and operators[-1] == '(':
                operators.pop()
            else:
                raise ValueError("Mismatched parentheses")
        i += 1

    # Apply remaining operators
    while operators:
        apply_operator(operators, values)

    # Check if there's exactly one value left
    if len(values) != 1:
        raise ValueError("Invalid expression")

    return values[0]

# Helper function to determine operator precedence
def precedence(op):
    if op in ('*', '/'):
        return 2
    elif op in ('+', '-'):
        return 1
    elif op == '^':
        return 3
    else:
        return 0
