def is_local_redirect(target: str, host: str) -> bool:
    # Check if target is a site-relative path
    if not target.startswith('/') or '/' in target[1:]:
        return False

    # Check if target starts with http:// or https://
    if not (target.startswith('http://') or target.startswith('https://')):
        return False

    # Normalize both host and target to lowercase for comparison
    host = host.lower()
    target = target.lower()

    # Check if the host part of the target matches the host parameter
    if target.split('/')[2] != host:
        return False

    # Check for any invalid characters in the target
    for char in target:
        if ord(char) < 32 or ord(char) > 127:
            return False

    return True
```

