def convert_base(number: str, from_base: int, to_base: int) -> str:
    if not (2 <= from_base <= 36) or not (2 <= to_base <= 36):
        raise ValueError("Base must be between 2 and 36.")

    if number == "":
        return "0"

    is_negative = number.startswith('-')
    number = number.lstrip('-')

    if not all(c in '0123456789abcdefghijklmnopqrstuvwxyz'[:from_base] for c in number):
        raise ValueError("Invalid character in number.")

    if number == "0":
        return "0"

    digits = '0123456789abcdefghijklmnopqrstuvwxyz'
    result = []

    while number:
        remainder = int(number) % to_base
        result.append(digits[remainder])
        number = str(int(number) // to_base)

    if is_negative:
        result.append('-')

    return ''.join(reversed(result))
