import ast

def matches_filter(expression: str, record: dict) -> bool:
    # Define a custom visitor for the AST to handle variable references
    class RecordVisitor(ast.NodeTransformer):
        def visit_Name(self, node):
            if node.id in record:
                return ast.Num(n=record[node.id])
            else:
                raise ValueError(f"Key '{node.id}' not found in record")

    # Parse the expression into an AST
    try:
        tree = ast.parse(expression, mode='eval')
    except SyntaxError as e:
        raise ValueError(f"Invalid expression: {e}")

    # Replace variable references with their corresponding values from the record
    tree = RecordVisitor().visit(tree)

    # Evaluate the modified AST
    try:
        result = eval(compile(tree, '<ast>', 'eval'))
    except ZeroDivisionError:
        raise ValueError("Division by zero encountered")
    except Exception as e:
        raise ValueError(f"Error evaluating expression: {e}")

