    # Define a custom visitor for the AST nodes
    class FilterVisitor(ast.NodeVisitor):
        def visit_Name(self, node):
            if node.id not in record:
                raise ValueError(f"Key '{node.id}' not found in record.")
            return record[node.id]

        def visit_BinOp(self, node):
            left = self.visit(node.left)
            right = self.visit(node.right)
            if isinstance(node.op, ast.Eq):
                return left == right
            elif isinstance(node.op, ast.NotEq):
                return left != right
            elif isinstance(node.op, ast.Lt):
                return left < right
            elif isinstance(node.op, ast.Le):
                return left <= right
            elif isinstance(node.op, ast.Gt):
                return left > right
            elif isinstance(node.op, ast.Ge):
                return left >= right
            else:
                raise ValueError(f"Unsupported operator '{node.op.__class__.__name__}'.")

        def visit_UnaryOp(self, node):
            operand = self.visit(node.operand)
            if isinstance(node.op, ast.Not):
                return not operand
            else:
                raise ValueError(f"Unsupported unary operator '{node.op.__class__.__name__}'.")

        def visit_Call(self, node):
            if node.func.id != 'and' and node.func.id != 'or':
                raise ValueError(f"Unsupported function '{node.func.id}'.")
            left = self.visit(node.args[0])
            right = self.visit(node.args[1])
            if node.func.id == 'and':
                return left and right
            else:
                return left or right

        def visit_Num(self, node):
            return node.n

        def visit_Str(self, node):
            return node.s

        def visit_Expr(self, node):
            return self.visit(node.value)

