def identifier_to_snake(name: str) -> str:
    # Split the name by underscores and hyphens
    parts = name.split('_') + name.split('-')

    # Filter out empty pieces
    parts = [part for part in parts if part]

    # Process each part to convert it to snake_case
    snake_case_parts = []
    for part in parts:
        if not part:
            continue

        # Initialize the first character
        snake_case_part = part[0].lower()

        # Iterate over the rest of the characters
        for i in range(1, len(part)):
            char = part[i]
            if char.isupper():
                snake_case_part += '_' + char.lower()
            elif char.isdigit():
                snake_case_part += char
            else:
                snake_case_part += '_' + char.lower()

        snake_case_parts.append(snake_case_part)

    # Join the processed parts with underscores
    return '_'.join(snake_case_parts)
