def smallest_lcs(a: str, b: str) -> str:
    m, n = len(a), len(b)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Build the DP table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    # Reconstruct the LCS
    lcs = []
    i, j = m, n
    while i > 0 and j > 0:
        if a[i - 1] == b[j - 1]:
            lcs.append(a[i - 1])
            i -= 1
            j -= 1
        elif dp[i - 1][j] > dp[i][j - 1]:
            i -= 1
        else:
            j -= 1

    # The LCS is built backwards, so reverse it
    lcs.reverse()

    # If no common characters, return an empty string
    if not lcs:
        return ""

    # Find the smallest LCS by comparing lexicographically
    smallest_lcs = lcs[0]
    for candidate in lcs:
        if candidate < smallest_lcs:
            smallest_lcs = candidate

    return smallest_lcs
