def run_bank_ops(balances: dict[str, int], ops: list[tuple]) -> tuple[dict[str, int], list[int]]:
    final_balances = balances.copy()
    failed_operations = []

    for i, (op_type, *args) in enumerate(ops):
        if op_type == 'deposit':
            account, amount = args
            if amount > 0:
                final_balances[account] += amount
            else:
                failed_operations.append(i)
        elif op_type == 'withdraw':
            account, amount = args
            if amount > 0 and final_balances.get(account, 0) >= amount:
                final_balances[account] -= amount
            else:
                failed_operations.append(i)
        elif op_type == 'transfer':
            source, target, amount = args
            if amount > 0 and final_balances.get(source, 0) >= amount + 2:
                final_balances[source] -= amount + 2
                final_balances[target] += amount
            else:
                failed_operations.append(i)
        elif op_type == 'freeze':
            account = args[0]
            if account in final_balances:
                final_balances[account] = -final_balances[account]
        elif op_type == 'unfreeze':
            account = args[0]
            if account in final_balances and final_balances[account] < 0:
                final_balances[account] = -final_balances[account]

    return final_balances, failed_operations
