import re

def is_allowed_webhook(url: str) -> bool:
    # Check if the URL starts with 'https://'
    if not url.startswith('https://'):
        return False

    # Remove any trailing dot from the hostname
    hostname = url.split('//')[1].split('/')[0]
    if hostname.endswith('.'):
        hostname = hostname[:-1]

    # Split the hostname into labels
    labels = hostname.split('.')

    # Check if there are at least two labels
    if len(labels) < 2:
        return False

    # Check if each label is valid
    for label in labels:
        if not re.match(r'^[a-zA-Z0-9-]+$', label):
            return False

    # Check if the last label is all lowercase letters
    if not labels[-1].islower():
        return False

    # Check if the hostname is not 'localhost' or ends with '.localhost'
    if hostname == 'localhost' or hostname.endswith('.localhost'):
        return False

    # Check if the port is either missing or 443
    if ':' in url:
        port = int(url.split(':')[1])
        if port != 443:
            return False

    return True
