def convert_base(number: str, from_base: int, to_base: int) -> str:
    if not 2 <= from_base <= 36 or not 2 <= to_base <= 36:
        raise ValueError("Base must be between 2 and 36.")

    if not number:
        return "0"

    if number[0] == '-':
        negative = True
        number = number[1:]
    else:
        negative = False

    if any(char not in '0123456789abcdefghijklmnopqrstuvwxyz' for char in number):
        raise ValueError("Invalid character in input number.")

    # Convert from base from_base to base 10
    decimal_value = 0
    for i, digit in enumerate(reversed(number)):
        value = ord(digit.lower()) - ord('0')
        if value >= from_base:
            raise ValueError("Invalid character in input number.")
        decimal_value += value * (from_base ** i)

    if decimal_value == 0:
        return "0"

    # Convert from base 10 to base to_base
    if to_base == 10:
        return str(decimal_value)

    result = ""
    while decimal_value > 0:
        remainder = decimal_value % to_base
        result = chr(ord('0') + remainder) + result
        decimal_value //= to_base

    if negative:
        result = '-' + result

    return result
