        while i < len(s) and s[i].isdigit():
            i += 1
        return int(s[:i]), i

    def apply_operator(operators, values):
        op = operators.pop()
        b = values.pop()
        a = values.pop()
        if op == '+':
            values.append(a + b)
        elif op == '-':
            values.append(a - b)
        elif op == '*':
            values.append(a * b)
        elif op == '/':
            if b == 0:
                raise ZeroDivisionError("Division by zero")
            values.append(a // b)
        elif op == '^':
            values.append(a ** b)

    def evaluate(tokens):
        values = []
        operators = []
        i = 0
        while i < len(tokens):
            if tokens[i] == '(':
                j = i + 1
                depth = 1
                while j < len(tokens) and depth > 0:
                    if tokens[j] == '(':
                        depth += 1
                    elif tokens[j] == ')':
                        depth -= 1
                    j += 1
                values.append(evaluate(tokens[i + 1:j - 1]))
                i = j
            elif tokens[i].isdigit():
                num, i = parse_number(tokens[i:])
                values.append(num)
            elif tokens[i] in '+-*/^':
                while (operators and operators[-1] in '^' and tokens[i] in '+-*/') or \
