def run_stack_machine(program: list[str]) -> list[int]:
    stack = []
    pc = 0  # Program Counter

    while pc < len(program):
        instruction = program[pc]
        parts = instruction.split()

        if parts[0] == "PUSH":
            try:
                value = int(parts[1])
                if len(stack) >= 1000:
                    raise ValueError("Stack overflow")
                stack.append(value)
            except ValueError:
                raise ValueError(f"Invalid PUSH instruction: {instruction}")
        elif parts[0] == "POP":
            if not stack:
                raise ValueError("POP instruction on empty stack")
            stack.pop()
        elif parts[0] == "DUP":
            if not stack:
                raise ValueError("DUP instruction on empty stack")
            stack.append(stack[-1])
        elif parts[0] == "SWAP":
            if len(stack) < 2:
                raise ValueError("SWAP instruction requires at least two elements")
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif parts[0] == "ADD":
            if len(stack) < 2:
                raise ValueError("ADD instruction requires at least two elements")
            a, b = stack.pop(), stack.pop()
            if a + b > 1000:
                raise RuntimeError("Result exceeds 1000")
            stack.append(a + b)
        elif parts[0] == "SUB":
            if len(stack) < 2:
                raise ValueError("SUB instruction requires at least two elements")
            a, b = stack.pop(), stack.pop()
            if a - b < -1000:
                raise RuntimeError("Result exceeds -1000")
            stack.append(a - b)
        elif parts[0] == "MUL":
            if len(stack) < 2:
                raise ValueError("MUL instruction requires at least two elements")
            a, b = stack.pop(), stack.pop()
            if a * b > 1000 or a * b < -1000:
                raise RuntimeError("Result exceeds 1000 or -1000")
            stack.append(a * b)
        elif parts[0] == "JMP":
            try:
                target = int(parts[1])
                if target < 0 or target >= len(program):
                    raise ValueError("JMP instruction out of range")
                pc = target
            except ValueError:
                raise ValueError(f"Invalid JMP instruction: {instruction}")
        elif parts[0] == "JZ":
            try:
                target = int(parts[1])
                if target < 0 or target >= len(program):
                    raise ValueError("JZ instruction out of range")
                if not stack:
                    raise ValueError("JZ instruction on empty stack")
                if stack[-1] == 0:
                    pc = target
            except ValueError:
                raise ValueError(f"Invalid JZ instruction: {instruction}")
        elif parts[0] == "HALT":
            break
        else:
            raise ValueError(f"Unknown instruction: {instruction}")

        pc += 1

    return stack
